        baseline: {
          ...subject,
          revision: baseCommit,
          files: baselineFiles,
          diff: "",
          evidence: subject.evidence.map((item) => ({
            ...item,
            evidenceId: `${baseCommit}:${item.criterionId}`,
            subjectRevision: baseCommit,
            codeSurfaces: baselineFiles.map((file) => file.path),
            automatedTest: null,
            observed:
