      const mount = join(verifierStore.directory, "mount");
      if (!existsSync(mount)) mkdirSync(mount, { mode: 0o700 });
      if (lstatSync(mount).isSymbolicLink() || realpathSync(mount) !== mount)
        throw new Error("feedback verifier mount alias");
