        execFileSync("git", ["init", "--quiet"], { cwd: mount, stdio: "pipe" });
      const mountRoot = execFileSync("git", ["rev-parse", "--show-toplevel"], {
        cwd: mount,
        encoding: "utf8",
        stdio: ["ignore", "pipe", "pipe"],
