import test from "node:test";
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import {
  mkdirSync,
  mkdtempSync,
  readFileSync,
  realpathSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import {
  FEEDBACK_SOURCE_PATHS,
  readFeedbackSource,
} from "../src/feedback-audit.js";

function fixture() {
  const root = realpathSync(
    mkdtempSync(join(tmpdir(), "dotln-feedback-source-")),
  );
  execFileSync("git", ["init", "--quiet", root], { stdio: "pipe" });
  for (const path of FEEDBACK_SOURCE_PATHS) {
    mkdirSync(dirname(join(root, path)), { recursive: true });
    writeFileSync(join(root, path), `// fixture source: ${path}\n`);
  }
  const manifest = {
    name: "@dotln/skeleton",
    version: "0.12.0",
    license: "Apache-2.0",
    private: true,
    scripts: { test: "node --test", prepublishOnly: "refuse" },
    exports: "./dist/index.js",
    dependencies: { typescript: "5.4.5" },
    extension: { version: "behavior-v1" },
  };
  const lock = {
    name: "fixture",
    version: "0.1.0",
    license: "Apache-2.0",
    lockfileVersion: 3,
    packages: {
      "": {
        version: "0.1.0",
        license: "Apache-2.0",
        workspaces: ["packages/*"],
      },
      "packages/kernel": { version: "0.2.1", license: "Apache-2.0" },
      "packages/compiler": { version: "0.6.0", license: "Apache-2.0" },
      "packages/skeleton": manifest,
      "node_modules/typescript": {
        version: "5.4.5",
        integrity: "fixture-integrity",
        resolved: "fixture:typescript",
        license: "Apache-2.0",
      },
      "packages/unknown": { version: "1.0.0", license: "fixture" },
    },
  };
  writeFileSync(
    join(root, "packages/skeleton/package.json"),
    JSON.stringify(manifest),
  );
  writeFileSync(join(root, "package-lock.json"), JSON.stringify(lock));
  return {
    root,
    manifest,
    lock,
    dispose: () => rmSync(root, { recursive: true, force: true }),
  };
}

test("feedback audit pins labeled projections and keeps release-only workspace metadata stable", () => {
  const f = fixture();
  try {
    const before = readFeedbackSource(f.root);
    const projected = before.files.filter((file) =>
      file.path.startsWith(".feedback-source/"),
    );
    assert.equal(projected.length, 2);
    for (const file of projected) {
      const capsule = JSON.parse(file.contents);
      assert.equal(capsule.projection, "feedback-package-projection-v1");
      assert.equal(file.path, `.feedback-source/${capsule.sourcePath}`);
      assert.ok(capsule.omitted.includes("/version"));
      assert.ok(capsule.omitted.includes("/license"));
      assert.equal("version" in capsule.value, false);
      assert.equal("license" in capsule.value, false);
    }
    f.manifest.version = "0.12.1";
    f.manifest.license = "fixture-new-license";
    f.lock.version = "0.1.1";
    f.lock.license = "fixture-new-license";
    for (const key of [
      "",
      "packages/kernel",
      "packages/compiler",
      "packages/skeleton",
    ] as const) {
      f.lock.packages[key].version += ".changed";
      f.lock.packages[key].license = "fixture-new-license";
    }
    writeFileSync(
      join(f.root, "packages/skeleton/package.json"),
      JSON.stringify(f.manifest, null, 2),
    );
    writeFileSync(
      join(f.root, "package-lock.json"),
      JSON.stringify(f.lock, null, 4),
    );
    assert.deepEqual(readFeedbackSource(f.root), before);
  } finally {
    f.dispose();
  }
});

test("feedback audit invalidates every declared runtime and fixture source byte", () => {
  const f = fixture();
  try {
    const before = readFeedbackSource(f.root);
    for (const path of FEEDBACK_SOURCE_PATHS.filter(
      (path) => !path.endsWith(".json"),
    )) {
      const full = join(f.root, path);
      const original = readFileSync(full, "utf8");
      writeFileSync(full, original + " ");
      assert.notEqual(readFeedbackSource(f.root).subject, before.subject, path);
      writeFileSync(full, original);
    }
  } finally {
    f.dispose();
  }
});

test("feedback audit keeps execution, dependency, publication, and unknown metadata in the subject", () => {
  const f = fixture();
  try {
    const before = readFeedbackSource(f.root).subject;
    const manifestPath = join(f.root, "packages/skeleton/package.json");
    for (const changed of [
      {
        ...f.manifest,
        scripts: { ...f.manifest.scripts, test: "different-test" },
      },
      {
        ...f.manifest,
        scripts: { ...f.manifest.scripts, prepublishOnly: "allow" },
      },
      { ...f.manifest, exports: "./different.js" },
      { ...f.manifest, dependencies: { typescript: "5.5.0" } },
      { ...f.manifest, private: false },
      { ...f.manifest, extension: { version: "behavior-v2" } },
    ]) {
      writeFileSync(manifestPath, JSON.stringify(changed));
      assert.notEqual(readFeedbackSource(f.root).subject, before);
    }
    writeFileSync(manifestPath, JSON.stringify(f.manifest));
    const lockPath = join(f.root, "package-lock.json");
    for (const field of [
      "version",
      "integrity",
      "resolved",
      "license",
    ] as const) {
      const lock = structuredClone(f.lock);
      lock.packages["node_modules/typescript"][field] += ".changed";
      writeFileSync(lockPath, JSON.stringify(lock));
      assert.notEqual(readFeedbackSource(f.root).subject, before, field);
    }
    const lock = structuredClone(f.lock);
    lock.packages["packages/unknown"].version = "2.0.0";
    writeFileSync(lockPath, JSON.stringify(lock));
    assert.notEqual(readFeedbackSource(f.root).subject, before);
    writeFileSync(lockPath, JSON.stringify({ ...f.lock, lockfileVersion: 4 }));
    assert.notEqual(readFeedbackSource(f.root).subject, before);
  } finally {
    f.dispose();
  }
});

test("feedback audit refuses malformed package projection inputs", () => {
  const f = fixture();
  try {
    for (const contents of [
      "{",
      "[]",
      "null",
      '{"packages":null}',
      '{"packages":{"packages/skeleton":[]}}',
    ]) {
      writeFileSync(join(f.root, "package-lock.json"), contents);
      assert.throws(() => readFeedbackSource(f.root));
    }
  } finally {
    f.dispose();
  }
});

#!/usr/bin/env node
import { readFileSync } from "node:fs";
import { personalFeedback } from "../packages/skeleton/dist/src/loadouts/feedback.js";
import { feedbackBoundary } from "../packages/skeleton/dist/src/feedback-boundary.js";

// Hook adapter: install only in an explicitly selected host/fixture. Missing builds fail closed.
try {
  if (process.argv.length !== 3)
    throw new Error("commit message path required");
  feedbackBoundary(
    personalFeedback(),
    {
      kind: "attribution",
      message: readFileSync(process.argv[2], "utf8"),
    },
    () => {},
  );
} catch {
  console.error(
    "Commit refused: message check failed or contains an AI attribution footer/trailer.",
  );
  process.exitCode = 1;
}

import { COMPILER_PACKAGE_VERSION } from "./artifact-identity.js";
import { canonicalStringify, fnv1a64 } from "./normalize.js";
import { repositoryPath, verificationLine } from "./verification.js";
import type { WorkOrder } from "./types.js";

/** Closed v1 handler vocabulary. Personal units live in the host's loadout. */
export const FEEDBACK_HANDLERS = {
  "decision-lineage": { kind: "pre-effect-guard", rung: 2 },
  "evidence-judgment": { kind: "evaluator", rung: 5 },
  "semantic-correction": { kind: "pure-reactor", rung: 3 },
  "application-evidence": { kind: "workflow-gate", rung: 6 },
  attribution: { kind: "script", rung: 1 },
  "writer-isolation": { kind: "pre-effect-guard", rung: 2 },
  "suppression-diff": { kind: "script", rung: 1 },
  "output-review": { kind: "workflow-gate", rung: 6 },
  "complete-scope": { kind: "workflow-gate", rung: 6 },
  "cleanup-scope": { kind: "pre-effect-guard", rung: 2 },
} as const;
export type FeedbackHandler = keyof typeof FEEDBACK_HANDLERS;
export interface FeedbackUnit {
  readonly unitId: string;
  readonly version: number;
  readonly incident: {
    readonly sourceRefs: readonly string[];
    readonly sourceTreatment: "synthesized-from-public-lineage";
    readonly summary: string;
    /** Retained source is referenced, not duplicated into every derivative. */
    readonly retainedSource: "public-reference";
  };
  readonly undesiredBehavior: string;
  readonly desiredBehavior: string;
  readonly scope: readonly string[];
  readonly trigger: FeedbackHandler;
  readonly mechanism: {
    readonly handler: FeedbackHandler;
    readonly version: 1;
    readonly rationale: string;
  };
  readonly enforcement: "hard" | "soft" | "advisory";
  readonly requiredEvidence: readonly string[];
  readonly regressionFixtures: readonly string[];
  readonly conflicts: readonly string[];
  readonly supersedes: readonly string[];
  readonly retirementCondition: string;
  readonly nextMaturityCondition: string;
  readonly proseEquivalent: string;
}
export interface CompiledFeedback {
  readonly contractVersion: "feedback-v1";
  readonly compilerPackageVersion: string;
  readonly units: readonly FeedbackUnit[];
  readonly mechanisms: readonly {
    readonly unitId: string;
    readonly handler: FeedbackHandler;
    readonly kind: string;
    readonly rung: number;
    readonly enforcement: FeedbackUnit["enforcement"];
  }[];
  readonly policyHash: string;
}
const requireFeedback: (ok: unknown, detail: string) => asserts ok = (
  ok,
  detail,
) => {
  if (!ok) throw new Error(`feedback contract: ${detail}`);
};
const strings = (
  values: readonly string[],
  name: string,
  nonempty = true,
): string[] => {
  requireFeedback(
    Array.isArray(values) &&
      values.length <= 100 &&
      (!nonempty || values.length > 0) &&
      values.every(verificationLine) &&
      new Set(values).size === values.length,
    name,
  );
  return [...values].sort();
};
const text = (value: string, name: string): string => {
  requireFeedback(verificationLine(value), name);
  return value;
};

/** Lower declared corrections to executable handlers, with no prompt emission. */
export function compileFeedbackUnits(
  input: readonly FeedbackUnit[],
): CompiledFeedback {
  requireFeedback(
    Array.isArray(input) && input.length <= 10,
    "bounded unit inventory",
  );
  const units = input
    .map((unit): FeedbackUnit => {
      requireFeedback(
        unit && typeof unit === "object" && unit.incident && unit.mechanism,
        "unit shape",
      );
      requireFeedback(
        Number.isSafeInteger(unit.version) && unit.version > 0,
        "unit version",
      );
      requireFeedback(
        Object.hasOwn(FEEDBACK_HANDLERS, unit.trigger) &&
          unit.mechanism.handler === unit.trigger &&
          unit.mechanism.version === 1,
        "unsupported mechanism or trigger",
      );
      requireFeedback(
        ["hard", "soft", "advisory"].includes(unit.enforcement),
        "enforcement",
      );
      requireFeedback(
        unit.incident.sourceTreatment === "synthesized-from-public-lineage" &&
          unit.incident.retainedSource === "public-reference",
        "declared source treatment",
      );
      const sourceRefs = strings(
        unit.incident.sourceRefs,
        "incident references",
      );
      requireFeedback(
        sourceRefs.every(
          (ref) =>
            repositoryPath(ref.split("#")[0]) &&
            !ref.startsWith("docs/intake/"),
        ),
        "public source references",
      );
      return {
        unitId: text(unit.unitId, "unit id"),
        version: unit.version,
        incident: {
          sourceRefs,
          sourceTreatment: unit.incident.sourceTreatment,
          summary: text(unit.incident.summary, "incident summary"),
          retainedSource: unit.incident.retainedSource,
        },
        undesiredBehavior: text(unit.undesiredBehavior, "undesired behavior"),
        desiredBehavior: text(unit.desiredBehavior, "desired behavior"),
        scope: strings(unit.scope, "scope"),
        trigger: unit.trigger,
        mechanism: {
          handler: unit.mechanism.handler,
          version: 1,
          rationale: text(
            unit.mechanism.rationale,
            "cheapest sufficient mechanism",
          ),
        },
        enforcement: unit.enforcement,
        requiredEvidence: strings(unit.requiredEvidence, "required evidence"),
        regressionFixtures: strings(
          unit.regressionFixtures,
          "regression fixtures",
        ),
        conflicts: strings(unit.conflicts, "conflicts", false),
        supersedes: strings(unit.supersedes, "supersedes", false),
        retirementCondition: text(
          unit.retirementCondition,
          "retirement condition",
        ),
        nextMaturityCondition: text(
          unit.nextMaturityCondition,
          "next maturity condition",
        ),
        proseEquivalent: text(unit.proseEquivalent, "prose equivalent"),
      };
    })
    .sort((a, b) => (a.unitId < b.unitId ? -1 : a.unitId > b.unitId ? 1 : 0));
  const ids = units.map((unit) => unit.unitId);
  requireFeedback(new Set(ids).size === ids.length, "duplicate unit id");
  requireFeedback(
    new Set(units.map((unit) => unit.trigger)).size === units.length,
    "duplicate handler",
  );
  for (const unit of units)
    requireFeedback(
      [...unit.conflicts, ...unit.supersedes].every((id) => !ids.includes(id)),
      "conflicting or superseded unit still equipped",
    );
  const contents = {
    contractVersion: "feedback-v1" as const,
    compilerPackageVersion: COMPILER_PACKAGE_VERSION,
    units,
    mechanisms: units.map((unit) => ({
      unitId: unit.unitId,
      handler: unit.mechanism.handler,
      ...FEEDBACK_HANDLERS[unit.mechanism.handler],
      enforcement: unit.enforcement,
    })),
  };
  return {
    ...contents,
    policyHash: `fnv1a64:${fnv1a64(canonicalStringify(contents))}`,
  };
}
export function assertCompiledFeedback(program: CompiledFeedback): void {
  requireFeedback(
    canonicalStringify(program) ===
      canonicalStringify(compileFeedbackUnits(program.units)),
    "compiled policy drift",
  );
}

/** These facts are supplied by the host, not accepted from worker result prose. */
export type FeedbackRequest =
  | {
      readonly kind: "decision-lineage";
      readonly proposedApproach: string;
      readonly requiredOutcomes: readonly string[];
      readonly preservedOutcomes: readonly string[];
      readonly rejected: readonly {
        readonly approach: string;
        readonly reason: string;
      }[];
      readonly explicitSupersessions: readonly string[];
      readonly proposedHardConstraints: readonly string[];
      readonly explicitHardConstraints: readonly string[];
    }
  | {
      readonly kind: "evidence-judgment";
      readonly subject: string;
      readonly claimed: "pass" | "fail";
      readonly operatorPreference: "pass" | "fail";
      readonly witnesses: readonly {
        readonly subject: string;
        readonly outcome: "pass" | "fail";
        readonly source: "independent" | "implementer";
        readonly evidenceRef: string;
      }[];
    }
  | {
      readonly kind: "application-evidence";
      readonly subject: string;
      readonly requiredChecks: readonly string[];
      readonly runs: readonly {
        readonly checkId: string;
        readonly subject: string;
        readonly exitCode: number;
        readonly executed: boolean;
        readonly evidenceRef: string;
      }[];
    }
  | { readonly kind: "attribution"; readonly message: string }
  | {
      readonly kind: "writer-isolation";
      readonly actorId: string;
      readonly worktree: string;
      readonly cwd: string;
      readonly gitRoot: string;
      readonly branch: string;
      readonly writable: boolean;
      readonly writers: readonly {
        readonly actorId: string;
        readonly worktree: string;
      }[];
    }
  | {
      readonly kind: "suppression-diff";
      readonly files: readonly {
        readonly path: string;
        readonly beforeComments: readonly string[];
        readonly afterComments: readonly string[];
      }[];
    }
  | {
      readonly kind: "output-review";
      readonly outputs: readonly {
        readonly path: string;
        readonly hash: string;
      }[];
      readonly reads: readonly {
        readonly path: string;
        readonly hash: string;
        readonly evidenceRef: string;
      }[];
    }
  | {
      readonly kind: "complete-scope";
      readonly required: readonly string[];
      readonly completed: readonly string[];
      readonly remaining: readonly string[];
      readonly status: string;
    }
  | {
      readonly kind: "cleanup-scope";
      readonly path: string;
      readonly allowedPaths: readonly string[];
      readonly adjacent: boolean;
      readonly unambiguous: boolean;
      readonly lowRisk: boolean;
      readonly obscuresDiff: boolean;
      readonly retainedEvidence: boolean;
      readonly requiredChecks: readonly string[];
      readonly coveredChecks: readonly string[];
      readonly assessmentRef: string;
    };
export interface FeedbackViolation {
  readonly unitId: string;
  readonly reason: string;
  readonly enforcement: FeedbackUnit["enforcement"];
}
export interface FeedbackVerdict {
  readonly allowed: boolean;
  readonly violations: readonly FeedbackViolation[];
  readonly eligibleUnits: readonly string[];
}

/** Precise footer/trailer predicate: ordinary discussion and human coauthors pass. */
export function hasAiAttribution(message: string): boolean {
  return message
    .split(/\r?\n/u)
    .some(
      (line) =>
        /^\s*Co-authored-by\s*:\s*(?:(?:Claude(?: Code)?|Codex|ChatGPT|OpenAI|Anthropic|AI)(?:\s|<)|[^<>]*<[^<>]*@(?:anthropic\.com|openai\.com)>)/iu.test(
          line,
        ) ||
        /^\s*(?:[\p{Emoji_Presentation}]\s*)?(?:Generated|Written|Co-authored) (?:with|by) (?:\[)?(?:Claude(?: Code)?|Codex|ChatGPT|OpenAI|AI)(?:\b|\])/iu.test(
          line,
        ),
    );
}

// Host-parsed comment bodies only; language parsing belongs to the adapter.
function suppressionComments(comments: readonly string[]): readonly string[] {
  return comments
    .flatMap((comment) => comment.split(/\r?\n/u))
    .map((line) => line.trim().replace(/^\*\s*/u, ""))
    .filter((line) =>
      /^(?:@ts-(?:ignore|expect-error|nocheck)\b|eslint-disable(?:-next-line|-line)?\b|tslint:disable\b)/u.test(
        line,
      ),
    );
}
const includesAll = (
  available: readonly string[],
  required: readonly string[],
) => required.length > 0 && required.every((id) => available.includes(id));
function reason(request: FeedbackRequest): string | null {
  switch (request.kind) {
    case "decision-lineage":
      if (!includesAll(request.preservedOutcomes, request.requiredOutcomes))
        return "desired outcome lost";
      if (
        request.rejected.some(
          (entry) =>
            entry.approach === request.proposedApproach &&
            !request.explicitSupersessions.includes(entry.approach),
        )
      )
        return "rejected approach repeated without explicit supersession";
      return request.proposedHardConstraints.every((id) =>
        request.explicitHardConstraints.includes(id),
      )
        ? null
        : "example or inference promoted to a hard constraint";
    case "evidence-judgment": {
      const witnesses = request.witnesses.filter(
        (item) =>
          item.subject === request.subject &&
          item.source === "independent" &&
          verificationLine(item.evidenceRef),
      );
      return witnesses.length > 0 &&
        witnesses.every((item) => item.outcome === request.claimed)
        ? null
        : "claim lacks consistent independent evidence";
    }
    case "application-evidence":
      return request.requiredChecks.length > 0 &&
        request.requiredChecks.every((id) => {
          const runs = request.runs.filter(
            (run) => run.checkId === id && run.subject === request.subject,
          );
          return (
            runs.length > 0 &&
            runs.every(
              (run) =>
                run.executed &&
                run.exitCode === 0 &&
                verificationLine(run.evidenceRef),
            )
          );
        })
        ? null
        : "required application check missing, stale, unexecuted, or failing";
    case "attribution":
      return hasAiAttribution(request.message)
        ? "AI attribution footer or trailer"
        : null;
    case "writer-isolation":
      return !request.writable ||
        (request.cwd === request.gitRoot &&
          request.cwd === request.worktree &&
          request.branch !== "main" &&
          request.branch !== "HEAD" &&
          request.branch.length > 0 &&
          request.writers.filter(
            (writer) => writer.worktree === request.worktree,
          ).length === 1 &&
          request.writers.some(
            (writer) =>
              writer.actorId === request.actorId &&
              writer.worktree === request.worktree,
          ))
        ? null
        : "write dispatch lacks a verified exclusive worktree";
    case "suppression-diff":
      return request.files.some((file) => {
        if (!/\.[cm]?[jt]sx?$/u.test(file.path)) return false;
        const remaining = [...suppressionComments(file.beforeComments)];
        return suppressionComments(file.afterComments).some((comment) => {
          const index = remaining.indexOf(comment);
          if (index < 0) return true;
          remaining.splice(index, 1);
          return false;
        });
      })
        ? "new lint/type suppression comment"
        : null;
    case "output-review":
      return request.outputs.length > 0 &&
        request.outputs.every((output) =>
          request.reads.some(
            (read) =>
              read.path === output.path &&
              read.hash === output.hash &&
              verificationLine(read.evidenceRef),
          ),
        )
        ? null
        : "output not read at its current bytes";
    case "complete-scope":
      return request.status === "completed" &&
        request.remaining.length === 0 &&
        includesAll(request.completed, request.required)
        ? null
        : "required work remains incomplete";
    case "cleanup-scope":
      return request.allowedPaths.includes(request.path) &&
        request.adjacent &&
        request.unambiguous &&
        request.lowRisk &&
        !request.obscuresDiff &&
        !request.retainedEvidence &&
        verificationLine(request.assessmentRef) &&
        includesAll(request.coveredChecks, request.requiredChecks)
        ? null
        : "cleanup needs a separate candidate or retained-evidence review";
  }
}
export function evaluateFeedback(
  program: CompiledFeedback,
  request: FeedbackRequest,
): FeedbackVerdict {
  assertCompiledFeedback(program);
  const kind: string = request.kind;
  requireFeedback(
    Object.hasOwn(FEEDBACK_HANDLERS, kind) && kind !== "semantic-correction",
    "boundary request kind",
  );
  const mechanisms = program.mechanisms.filter(
    (item) => item.handler === request.kind,
  );
  const violation = mechanisms.length ? reason(request) : null;
  const violations =
    violation === null
      ? []
      : mechanisms.map((item) => ({
          unitId: item.unitId,
          enforcement: item.enforcement,
          reason: violation,
        }));
  return {
    allowed: !violations.some((item) => item.enforcement === "hard"),
    violations,
    eligibleUnits: mechanisms.map((item) => item.unitId),
  };
}

export const SEMANTIC_CORRECTIONS = [
  "OperatorCorrectionReceived",
  "OperatorReportsRegression",
  "OperatorRejectsUnsupportedAssumption",
  "OperatorReportsRepeatedFailure",
] as const;
export interface CorrectionState {
  readonly allowedEffects: readonly string[];
  readonly destructiveEffects: readonly string[];
  readonly scopeExpansionAllowed: boolean;
  readonly preserveEvidence: boolean;
  readonly diagnosisRequired: boolean;
  readonly corrections: readonly string[];
}
/** Monotone meet: even a mistakenly classified typed event can only tighten. */
export function applyFeedbackCorrection(
  program: CompiledFeedback,
  state: CorrectionState,
  event: { readonly type: string; readonly eventId: string },
): CorrectionState {
  assertCompiledFeedback(program);
  if (
    !program.mechanisms.some(
      (item) =>
        item.handler === "semantic-correction" && item.enforcement === "hard",
    ) ||
    !SEMANTIC_CORRECTIONS.some((type) => type === event.type) ||
    state.corrections.includes(event.eventId)
  )
    return state;
  requireFeedback(verificationLine(event.eventId), "correction event identity");
  return {
    ...state,
    allowedEffects: state.allowedEffects.filter(
      (effect) =>
        !effect.includes("*") && !state.destructiveEffects.includes(effect),
    ),
    scopeExpansionAllowed: false,
    preserveEvidence: true,
    diagnosisRequired: true,
    corrections: [...state.corrections, event.eventId],
  };
}

export interface FeedbackObservation {
  readonly unitId: string;
  readonly episodeId: string;
  readonly source: "fixture" | "live";
  readonly activated: boolean;
  readonly prevented: boolean;
  readonly falseActivation: boolean;
  readonly overridden: boolean;
}
export function feedbackMaturity(
  program: CompiledFeedback,
  observations: readonly FeedbackObservation[],
) {
  assertCompiledFeedback(program);
  const seen = new Set<string>();
  for (const observation of observations) {
    const key = `${observation.unitId}:${observation.episodeId}`;
    requireFeedback(
      program.units.some((unit) => unit.unitId === observation.unitId) &&
        verificationLine(observation.episodeId) &&
        !seen.has(key) &&
        ["fixture", "live"].includes(observation.source) &&
        [
          observation.activated,
          observation.prevented,
          observation.falseActivation,
          observation.overridden,
        ].every((value) => typeof value === "boolean") &&
        (!(
          observation.prevented ||
          observation.falseActivation ||
          observation.overridden
        ) ||
          observation.activated) &&
        !(observation.prevented && observation.falseActivation),
      "maturity observation",
    );
    seen.add(key);
  }
  const count = (unitId: string, source: "fixture" | "live") => {
    const rows = observations.filter(
      (item) => item.unitId === unitId && item.source === source,
    );
    return {
      eligibleEpisodes: rows.length,
      activations: rows.filter((item) => item.activated).length,
      incidentsPrevented: rows.filter((item) => item.prevented).length,
      falseActivations: rows.filter((item) => item.falseActivation).length,
      overrides: rows.filter((item) => item.overridden).length,
    };
  };
  return program.units.map((unit) => ({
    unitId: unit.unitId,
    version: unit.version,
    currentMechanism: unit.mechanism.handler,
    nextMaturityCondition: unit.nextMaturityCondition,
    awakened: false as const,
    fixture: count(unit.unitId, "fixture"),
    live: count(unit.unitId, "live"),
  }));
}

/** One bounded read-only work order; execution is a fixed host subprocess. */
export function compileFeedbackAudit(
  program: CompiledFeedback,
  repo: string,
  baseCommit: string,
  subject: string,
): WorkOrder {
  assertCompiledFeedback(program);
  requireFeedback(
    verificationLine(repo) &&
      /^[a-f0-9]{40}$/u.test(baseCommit) &&
      verificationLine(subject),
    "audit subject",
  );
  return {
    workOrderId: "WO-011-feedback-audit",
    repo,
    baseCommit,
    objective:
      "Audit this repository's ten FeedbackUnits through their executable regression and removal fixtures.",
    acceptanceCriteria: [
      "Every equipped unit's regression passes and fails when that mechanism is removed.",
      "Report measured instruction bytes using the WO-004 accounting method.",
    ],
    knownFacts: [
      `Pinned source: ${subject}`,
      `Equipped feedback: ${program.policyHash}`,
    ],
    decisions: [
      "Execute the fixed local regression runner; independently verify its pinned evidence.",
    ],
    constraints: [
      "Read-only source access",
      "Controlled fixtures do not establish general live prevention rates",
    ],
    nonGoals: [
      "Change repository source",
      "Publish",
      "General self-hosting switchover",
    ],
    allowedOperations: ["feedback.audit"],
    prohibitedOperations: ["repo.write", "repo.delete", "publish"],
    requiredEvidence: [
      "present-and-removed-fixtures",
      "context-accounting",
      "independent-verification",
    ],
    outputContract: {
      type: "feedback-audit-v1",
      policyHash: program.policyHash,
      subject,
    },
  };
}

import { canonicalStringify, fnv1a64 } from "./normalize.js";
import type {
  ActiveMechanic,
  AmbientEffect,
  ArtifactIdentityV1,
  CompilationEnvironment,
  CompiledProgram,
  ComponentManifestEntry,
  LoadoutGraph,
  SupportFacet,
} from "./types.js";

// Source constant, checked against package.json in the executable evidence.
// Reading a package manifest at runtime would introduce I/O into compilation.
export const COMPILER_PACKAGE_VERSION = "0.8.0";
export const COMPONENT_DEFINITION_HASH_SCHEME =
  "dotln-component-definition-fnv1a64-v1" as const;
export const COMPONENT_DEFINITION_DOMAIN = "dotln:component-definition:v1";

/** The definition must come from normalizeLoadoutGraph, not a source view. */
export const componentDefinitionPreimage = (
  componentKind: ComponentManifestEntry["componentKind"],
  definition: ActiveMechanic | SupportFacet | AmbientEffect,
): string =>
  canonicalStringify({
    domain: COMPONENT_DEFINITION_DOMAIN,
    componentKind,
    definition,
  });

/** Called only after successful compilation, with its normalized source. */
export const deriveArtifactIdentity = (
  graph: LoadoutGraph,
  program: CompiledProgram,
  environment: CompilationEnvironment,
  semanticHash: string,
): ArtifactIdentityV1 => ({
  schemaVersion: 1,
  compilerContractVersion: program.compilerVersion,
  compilerPackageVersion: COMPILER_PACKAGE_VERSION,
  semanticHash,
  compilationEnvironment: JSON.parse(canonicalStringify(environment)),
  authorityExpiresAt: program.authorityEnvelope.expiresAt,
  componentDefinitions: program.componentManifest.map((entry) => {
    const definition =
      entry.componentKind === "active-mechanic"
        ? graph.activeMechanics.find(
            (value) => value.activeMechanicId === entry.componentId,
          )
        : entry.componentKind === "support-facet"
          ? graph.supportFacets.find(
              (value) => value.supportFacetId === entry.componentId,
            )
          : graph.ambientEffects.find(
              (value) => value.ambientEffectId === entry.componentId,
            );
    if (definition === undefined || definition.version !== entry.version)
      throw new Error(
        "component manifest has no matching normalized definition",
      );
    return {
      componentKind: entry.componentKind,
      componentId: entry.componentId,
      version: entry.version,
      hashScheme: COMPONENT_DEFINITION_HASH_SCHEME,
      definitionHash: `fnv1a64:${fnv1a64(componentDefinitionPreimage(entry.componentKind, definition))}`,
    };
  }),
});

import { COMPILER_PACKAGE_VERSION } from "./artifact-identity.js";
import { canonicalStringify, fnv1a64 } from "./normalize.js";
import type { WorkOrder } from "./types.js";

export type ClaimType = "state" | "behavior";
export type EvidenceSource = "synthetic-fixture" | "live";
export interface AcceptanceCriterion {
  readonly criterionId: string;
  readonly description: string;
  readonly claimType: ClaimType;
  readonly evidenceSource: EvidenceSource;
  /** Includes dependencies whose substantive change requires another check. */
  readonly codeSurfaces: readonly string[];
  readonly requiredChecks: readonly string[];
}
export interface VerificationEvidence {
  readonly evidenceId: string;
  readonly criterionId: string;
  readonly checkId: string;
  readonly claimType: ClaimType;
  readonly source: EvidenceSource;
  readonly subjectRevision: string;
  readonly codeSurfaces: readonly string[];
  readonly automatedTest: string | null;
  readonly observed: string;
  readonly expected: string;
  readonly outcome: "pass" | "fail" | "unavailable";
  readonly reproductionSteps: readonly string[];
}
export interface VerificationFinding {
  readonly findingId: string;
  readonly criterionId: string;
  readonly severity: "blocking" | "major" | "minor";
  readonly observed: string;
  readonly expected: string;
  readonly reproductionSteps: readonly string[];
  readonly evidenceRefs: readonly string[];
  readonly likelySurface: readonly string[];
}
export interface Evaluation {
  readonly criterionId: string;
  readonly claimType: ClaimType;
  readonly verdict: "pass" | "fail" | "unverified";
  readonly evidenceRefs: readonly string[];
  /** Reserved, explicitly empty until their comparison consumers arrive. */
  readonly exemplarRefs: readonly string[];
  readonly dissentRefs: readonly string[];
}
export interface RepositoryFile {
  readonly path: string;
  readonly contents: string;
}
export interface VerificationSubject {
  readonly repo: string;
  readonly baseCommit: string;
  readonly revision: string;
  readonly diff: string;
  /** Explicit host-read repository projection; no transcript or result prose. */
  readonly files: readonly RepositoryFile[];
  readonly evidence: readonly VerificationEvidence[];
}
export interface VerificationTask {
  readonly contractVersion: "verification-v1";
  readonly compilerPackageVersion: string;
  readonly inputHash: string;
  readonly role: "verifier" | "repairer";
  readonly workOrder: WorkOrder;
  readonly criteria: readonly AcceptanceCriterion[];
  readonly subject: VerificationSubject;
  readonly finding: VerificationFinding | null;
}

export const verificationLine = (value: unknown): value is string =>
  typeof value === "string" &&
  value.length > 0 &&
  value.length <= 2000 &&
  !/[\u0000-\u001f\u007f\u2028\u2029]/u.test(value);
export const repositoryPath = (value: unknown): value is string =>
  verificationLine(value) &&
  value.length <= 256 &&
  !value.startsWith("/") &&
  !value.includes("\\") &&
  value
    .split("/")
    .every(
      (part) => part !== "" && part !== "." && part !== ".." && part !== ".git",
    );
const requireValue: (valid: unknown, detail: string) => asserts valid = (
  valid,
  detail,
) => {
  if (!valid) throw new Error(`verification contract: ${detail}`);
};
const lines = (
  values: readonly string[],
  name: string,
  nonempty = true,
): string[] => {
  requireValue(
    Array.isArray(values) &&
      (!nonempty || values.length > 0) &&
      values.length <= 100 &&
      values.every(verificationLine),
    name,
  );
  requireValue(new Set(values).size === values.length, `duplicate ${name}`);
  return [...values];
};

export function copyCriterion(value: AcceptanceCriterion): AcceptanceCriterion {
  requireValue(
    verificationLine(value.criterionId) && verificationLine(value.description),
    "criterion identity",
  );
  requireValue(["state", "behavior"].includes(value.claimType), "claim type");
  requireValue(
    ["synthetic-fixture", "live"].includes(value.evidenceSource),
    "evidence source",
  );
  const codeSurfaces = lines(value.codeSurfaces, "criterion surfaces");
  requireValue(codeSurfaces.every(repositoryPath), "criterion paths");
  return {
    criterionId: value.criterionId,
    description: value.description,
    claimType: value.claimType,
    evidenceSource: value.evidenceSource,
    codeSurfaces,
    requiredChecks: lines(value.requiredChecks, "required checks"),
  };
}
export function copyFinding(value: VerificationFinding): VerificationFinding {
  requireValue(
    verificationLine(value.findingId) &&
      verificationLine(value.criterionId) &&
      verificationLine(value.observed) &&
      verificationLine(value.expected),
    "finding fields",
  );
  requireValue(
    ["blocking", "major", "minor"].includes(value.severity),
    "finding severity",
  );
  const likelySurface = lines(value.likelySurface, "likely surfaces");
  requireValue(likelySurface.every(repositoryPath), "finding paths");
  return {
    findingId: value.findingId,
    criterionId: value.criterionId,
    severity: value.severity,
    observed: value.observed,
    expected: value.expected,
    reproductionSteps: lines(value.reproductionSteps, "reproduction steps"),
    evidenceRefs: lines(value.evidenceRefs, "finding evidence"),
    likelySurface,
  };
}
export function copySubject(value: VerificationSubject): VerificationSubject {
  requireValue(
    verificationLine(value.repo) &&
      verificationLine(value.baseCommit) &&
      verificationLine(value.revision),
    "subject identity",
  );
  requireValue(
    typeof value.diff === "string" && value.diff.length <= 100_000,
    "subject diff",
  );
  requireValue(
    Array.isArray(value.files) &&
      value.files.length > 0 &&
      value.files.length <= 100,
    "repository snapshot",
  );
  const files = value.files.map((file) => {
    requireValue(
      repositoryPath(file.path) &&
        typeof file.contents === "string" &&
        file.contents.length <= 100_000,
      "repository file",
    );
    return { path: file.path, contents: file.contents };
  });
  requireValue(
    new Set(files.map((file) => file.path)).size === files.length,
    "duplicate repository file",
  );
  requireValue(
    Array.isArray(value.evidence) && value.evidence.length <= 100,
    "subject evidence",
  );
  const evidence = value.evidence.map((item): VerificationEvidence => {
    requireValue(
      verificationLine(item.evidenceId) &&
        verificationLine(item.criterionId) &&
        verificationLine(item.checkId) &&
        verificationLine(item.observed) &&
        verificationLine(item.expected),
      "evidence fields",
    );
    requireValue(
      item.subjectRevision === value.revision &&
        ["state", "behavior"].includes(item.claimType) &&
        ["synthetic-fixture", "live"].includes(item.source) &&
        ["pass", "fail", "unavailable"].includes(item.outcome),
      "evidence provenance",
    );
    requireValue(
      item.automatedTest === null || verificationLine(item.automatedTest),
      "automated test",
    );
    const codeSurfaces = lines(item.codeSurfaces, "evidence surfaces");
    requireValue(codeSurfaces.every(repositoryPath), "evidence paths");
    return {
      evidenceId: item.evidenceId,
      criterionId: item.criterionId,
      checkId: item.checkId,
      claimType: item.claimType,
      source: item.source,
      subjectRevision: item.subjectRevision,
      codeSurfaces,
      automatedTest: item.automatedTest,
      observed: item.observed,
      expected: item.expected,
      outcome: item.outcome,
      reproductionSteps: lines(item.reproductionSteps, "evidence reproduction"),
    };
  });
  requireValue(
    new Set(evidence.map((item) => item.evidenceId)).size === evidence.length,
    "duplicate evidence id",
  );
  return {
    repo: value.repo,
    baseCommit: value.baseCommit,
    revision: value.revision,
    diff: value.diff,
    files,
    evidence,
  };
}

/** Positive construction is the blinding boundary, including nested values. */
export function compileVerificationTask(
  workOrderId: string,
  criteriaInput: readonly AcceptanceCriterion[],
  subjectInput: VerificationSubject,
  findingInput: VerificationFinding | null = null,
): VerificationTask {
  requireValue(verificationLine(workOrderId), "work order id");
  requireValue(
    Array.isArray(criteriaInput) &&
      criteriaInput.length > 0 &&
      criteriaInput.length <= 100,
    "criteria",
  );
  const criteria = criteriaInput.map(copyCriterion);
  requireValue(
    new Set(criteria.map((value) => value.criterionId)).size ===
      criteria.length,
    "duplicate criterion id",
  );
  const subject = copySubject(subjectInput);
  const finding = findingInput === null ? null : copyFinding(findingInput);
  requireValue(
    finding === null ||
      (finding.severity === "blocking" &&
        criteria.some(
          (criterion) => criterion.criterionId === finding.criterionId,
        )),
    "repair requires a blocking finding",
  );
  requireValue(
    criteria.every((criterion) =>
      criterion.codeSurfaces.every((path) =>
        subject.files.some((file) => file.path === path),
      ),
    ),
    "criterion outside repository snapshot",
  );
  requireValue(
    finding === null ||
      finding.likelySurface.every((path) =>
        criteria.some((criterion) => criterion.codeSurfaces.includes(path)),
      ),
    "repair outside criterion surfaces",
  );
  const role = finding === null ? "verifier" : "repairer";
  const workOrder: WorkOrder = {
    workOrderId,
    objective:
      finding === null
        ? "Independently verify the supplied acceptance criteria against the pinned repository and witnessed evidence."
        : `Repair ${finding.findingId}: ${finding.expected}`,
    acceptanceCriteria: criteria.map(
      (criterion) => `${criterion.criterionId}: ${criterion.description}`,
    ),
    knownFacts: [
      "Repository access is the explicit host-read snapshot in this capsule.",
    ],
    decisions: [],
    constraints: [
      "Evidence source and claim type must match each criterion.",
      "Worker completion is a self-report; only host-admitted verifier evidence updates acceptance.",
    ],
    nonGoals: [
      "Independent code review",
      "Unrelated changes",
      "Live-integration claims from synthetic fixtures",
    ],
    repo: subject.repo,
    baseCommit: subject.revision,
    allowedOperations: [
      finding === null ? "verification.evaluate" : "repair.propose",
    ],
    prohibitedOperations: [
      "repo.write",
      "repo.delete",
      "network",
      "transcript.read",
      "self.certify",
    ],
    requiredEvidence: criteria.flatMap((criterion) => criterion.requiredChecks),
    outputContract: {
      type: finding === null ? "verification-result-v1" : "repair-proposal-v1",
    },
  };
  const contents: Omit<VerificationTask, "inputHash"> = {
    contractVersion: "verification-v1" as const,
    compilerPackageVersion: COMPILER_PACKAGE_VERSION,
    role,
    workOrder,
    criteria,
    subject,
    finding,
  };
  return {
    ...contents,
    inputHash: `fnv1a64:${fnv1a64(canonicalStringify(contents))}`,
  };
}

export function assertVerificationTask(task: VerificationTask): void {
  const expected = compileVerificationTask(
    task.workOrder.workOrderId,
    task.criteria,
    task.subject,
    task.finding,
  );
  requireValue(
    canonicalStringify(task) === canonicalStringify(expected),
    "compiled capsule drift",
  );
}

/** Semantic repair policy: exact source bytes, including dependency surfaces. */
export function changedVerificationSurfaces(
  before: VerificationSubject,
  after: VerificationSubject,
): readonly string[] {
  const paths = new Set(
    [...before.files, ...after.files].map((file) => file.path),
  );
  return [...paths]
    .filter(
      (path) =>
        before.files.find((file) => file.path === path)?.contents !==
        after.files.find((file) => file.path === path)?.contents,
    )
    .sort();
}

export function affectedVerificationCriteria(
  criteria: readonly AcceptanceCriterion[],
  changed: readonly string[],
): readonly string[] {
  // An undeclared dependency is uncertainty, not permission to retain evidence.
  const unknown = changed.some(
    (path) =>
      !criteria.some((criterion) => criterion.codeSurfaces.includes(path)),
  );
  return criteria
    .filter(
      (criterion) =>
        unknown ||
        criterion.codeSurfaces.some((path) => changed.includes(path)),
    )
    .map((criterion) => criterion.criterionId);
}

import { createHash } from "node:crypto";
import { readFileSync, realpathSync } from "node:fs";
import { execFileSync } from "node:child_process";
import {
  evaluateFeedback,
  type CompiledFeedback,
  type FeedbackRequest,
  type FeedbackVerdict,
} from "@dotln/compiler";
import { feedbackSourceComments } from "./feedback-source-comments.js";

export type FeedbackBoundaryRequest =
  | Exclude<FeedbackRequest, { readonly kind: "suppression-diff" }>
  | {
      readonly kind: "suppression-diff";
      readonly files: readonly {
        readonly path: string;
        readonly before: string;
        readonly after: string;
      }[];
    };

export class FeedbackRefused extends Error {
  constructor(readonly verdict: FeedbackVerdict) {
    super(
      verdict.violations
        .map((item) => `${item.unitId}: ${item.reason}`)
        .join("; "),
    );
  }
}
/** Only host-derived facts enter here. A model cannot call this with self-authored evidence. */
export function feedbackBoundary<T>(
  program: CompiledFeedback,
  facts: FeedbackBoundaryRequest,
  effect: () => T,
): T {
  const request: FeedbackRequest =
    facts.kind === "suppression-diff"
      ? {
          kind: facts.kind,
          files: facts.files.map((file) => ({
            path: file.path,
            beforeComments: feedbackSourceComments(file.path, file.before),
            afterComments: feedbackSourceComments(file.path, file.after),
          })),
        }
      : facts;
  const verdict = evaluateFeedback(program, request);
  if (!verdict.allowed) throw new FeedbackRefused(verdict);
  return effect();
}
export const feedbackContentHash = (bytes: string | Uint8Array): string =>
  `sha256:${createHash("sha256").update(bytes).digest("hex")}`;
export function feedbackReadOutput(path: string, evidenceRef: string) {
  const contents = readFileSync(path);
  return {
    contents,
    receipt: {
      path: realpathSync(path),
      hash: feedbackContentHash(contents),
      evidenceRef,
    },
  };
}
/** Caller owns a reservation lock spanning this observation and writable dispatch. */
export function feedbackWriterFacts(
  cwd: string,
  actorId: string,
  writers: readonly { readonly actorId: string; readonly worktree: string }[],
): Extract<FeedbackRequest, { readonly kind: "writer-isolation" }> {
  const physical = realpathSync(cwd);
  const git = (...args: string[]) =>
    execFileSync("git", args, {
      cwd: physical,
      encoding: "utf8",
      stdio: ["ignore", "pipe", "pipe"],
      timeout: 5000,
    }).trim();
  const gitRoot = realpathSync(git("rev-parse", "--show-toplevel"));
  return {
    kind: "writer-isolation",
    actorId,
    cwd: physical,
    gitRoot,
    worktree: gitRoot,
    branch: git("rev-parse", "--abbrev-ref", "HEAD"),
    writable: true,
    writers: writers.map((writer) => ({
      actorId: writer.actorId,
      worktree: realpathSync(writer.worktree),
    })),
  };
}

import { createRequire } from "node:module";
import type * as TypeScript from "typescript";

const require = createRequire(import.meta.url);
let parser: typeof TypeScript | undefined;

/** Parse token boundaries first so regex, templates, and JSX text cannot impersonate trivia. */
export function feedbackSourceComments(
  path: string,
  source: string,
): readonly string[] {
  if (!/\.[cm]?[jt]sx?$/u.test(path)) return [];
  const ts = (parser ??= require("typescript") as typeof TypeScript);
  if (ts.version !== "5.4.5")
    throw new Error("feedback source parser version drift");
  const kind = path.endsWith(".tsx")
    ? ts.ScriptKind.TSX
    : path.endsWith(".jsx")
      ? ts.ScriptKind.JSX
      : /\.[cm]?js$/u.test(path)
        ? ts.ScriptKind.JS
        : ts.ScriptKind.TS;
  const file = ts.createSourceFile(
    path,
    source,
    ts.ScriptTarget.Latest,
    true,
    kind,
  );
  const tokens: { start: number; end: number }[] = [];
  const visit = (node: TypeScript.Node): void => {
    // JSDoc is already comment trivia, not another source-token subtree.
    if (
      node.kind >= ts.SyntaxKind.FirstJSDocNode &&
      node.kind <= ts.SyntaxKind.LastJSDocNode
    )
      return;
    if (node.kind <= ts.SyntaxKind.LastToken) {
      tokens.push({ start: node.getStart(file), end: node.end });
      return;
    }
    for (const child of node.getChildren(file)) visit(child);
  };
  visit(file);
  tokens.sort((a, b) => a.start - b.start || a.end - b.end);
  const ranges = new Map<number, TypeScript.CommentRange>();
  let cursor = 0;
  for (const token of [
    ...tokens,
    { start: source.length, end: source.length },
  ]) {
    if (token.start > cursor) {
      for (const range of [
        ...(ts.getLeadingCommentRanges(source, cursor) ?? []),
        ...(ts.getTrailingCommentRanges(source, cursor) ?? []),
      ]) {
        if (range.pos >= cursor && range.end <= token.start)
          ranges.set(range.pos, range);
      }
    }
    cursor = Math.max(cursor, token.end);
  }
  return [...ranges.values()]
    .sort((a, b) => a.pos - b.pos)
    .map((range) =>
      source.slice(
        range.pos + 2,
        range.end -
          (range.kind === ts.SyntaxKind.MultiLineCommentTrivia ? 2 : 0),
      ),
    );
}

