    execFileSync(
      "git",
      [
        "ls-tree",
        "-r",
        "--name-only",
        "-z",
        baseCommit,
        "--",
        ...source.files.map((file) => file.path),
      ],
      {
        cwd: options.root,
        encoding: "utf8",
        stdio: ["ignore", "pipe", "pipe"],
        timeout: 5000,
      },
    ).split("\0"),
  );
  const baselineFiles = source.files
    .filter((file) => baselinePaths.has(file.path))
    .map((file) => ({
      path: file.path,
      contents: execFileSync("git", ["show", `${baseCommit}:${file.path}`], {
        cwd: options.root,
        encoding: "utf8",
        stdio: ["ignore", "pipe", "pipe"],
        timeout: 5000,
