export const MINUTE = SEIRI_MINUTE;
export const WORKSTREAM = "ws_repo_garden";
export const EPISODE = "ep_seiri_1";
export const ACTOR = "repo-gardener";
export const PULSE_SCHEDULE = SEIRI_PULSE_SCHEDULE;
export const QUEUED_PULSE = SEIRI_QUEUED_PULSE;

export type Candidate = Readonly<{
  path: string;
  classification: string;
  evidence: readonly string[];
}>;

export type Loadout = LoadoutGraph;

type RuntimePolicy = Readonly<{ maintenance: string }>;

export type RuntimeState = Readonly<{
  feedback?: JsonValue;
  verification?: JsonValue;
  presence: "away" | "returned";
  rngState: number;
  policy: RuntimePolicy;
  loadout: JsonValue;
  artifactIdentity: JsonValue;
  compilationEnvironment: JsonValue;
  equippedEventId: string | null;
  identityEnforcementEventId: string | null;
  artifactIdentityBlocked: boolean;
  workOrder: JsonValue;
  candidates: readonly Candidate[];
  verified: boolean;
  verificationCompleted: boolean;
  pulseSeen: boolean;
  inspectionCompleted: boolean;
  deletionRefused: boolean;
  queuedPulseNoOp: boolean;
  authority: JsonValue;
  revocationEvents: readonly JsonValue[];
  program: JsonValue;
  commandResult: JsonValue;
  pendingCommand: JsonValue;
  authorizationEvidence: readonly string[];
  deletionPaths: readonly string[];
  refusalReason: JsonValue;
  persistedEffect: JsonValue;
  noOpEvidence: readonly string[];
  cancelledScheduleIds: readonly string[];
  activeScheduleIds: readonly string[];
  redispatchedCommandIds: readonly string[];
  beaconObservations: readonly JudgedBeacon[];
  beaconSweep: JsonValue;
  workerEpisodeId: string | null;
  workerLeaseExpired: boolean;
}>;

export const loadout: Loadout = seiriLoadout;

const statePresence = (state: JsonValue): JsonValue | undefined =>
  state !== null && !Array.isArray(state) && typeof state === "object"
    ? (state as Readonly<Record<string, JsonValue>>)["presence"]
    : undefined;

export const seiriPredicates: PredicateRegistry = {
  "operator.away": { 1: ({ state }) => statePresence(state) === "away" },
  "operator.returned": {
    1: ({ state }) => statePresence(state) === "returned",
  },
  "operator.return-event": {
    1: ({ state, event }) =>
      statePresence(state) === "returned" &&
      event?.type === "OperatorPresenceChanged" &&
      event.payload !== null &&
      !Array.isArray(event.payload) &&
      typeof event.payload === "object" &&
      (event.payload as Readonly<Record<string, JsonValue>>)["presence"] ===
        "returned",
  },
};

export function compileLoadoutProgram(
  equipped: Loadout,
  baseCommit = "fixture-base",
): CompiledProgram {
  const result = compileLoadout(equipped, seiriEnvironment(baseCommit));
  if (!result.ok)
    throw new Error(
      result.diagnostics.map((entry) => entry.message).join("\n"),
    );
  return result.program;
}

export function compileWorkOrder(
  equipped: Loadout,
  baseCommit = "fixture-base",
): WorkOrder {
  return compileLoadoutProgram(equipped, baseCommit).workOrder;
}

export const initialState = (): RuntimeState => ({
  presence: "returned",
  rngState: 17,
  policy: { maintenance: "absent-only" },
  loadout: null,
  artifactIdentity: null,
  compilationEnvironment: null,
  equippedEventId: null,
  identityEnforcementEventId: null,
  artifactIdentityBlocked: false,
  workOrder: null,
  candidates: [],
  verified: false,
  verificationCompleted: false,
  pulseSeen: false,
  inspectionCompleted: false,
  deletionRefused: false,
  queuedPulseNoOp: false,
  authority: null,
  revocationEvents: [],
  program: null,
  commandResult: null,
  pendingCommand: null,
  authorizationEvidence: [],
  deletionPaths: [],
  refusalReason: null,
  persistedEffect: null,
  noOpEvidence: [],
  cancelledScheduleIds: [],
  activeScheduleIds: [],
  redispatchedCommandIds: [],
  beaconObservations: [],
  beaconSweep: null,
  workerEpisodeId: null,
  workerLeaseExpired: false,
});

const asObject = (
  value: JsonValue,
): Readonly<Record<string, JsonValue>> | undefined =>
  value !== null && !Array.isArray(value) && typeof value === "object"
    ? (value as Readonly<Record<string, JsonValue>>)
    : undefined;

const stringField = (value: JsonValue, key: string): string | undefined => {
  const candidate = asObject(value)?.[key];
  return typeof candidate === "string" ? candidate : undefined;
};

const stringArrayField = (value: JsonValue, key: string): readonly string[] => {
  const candidate = asObject(value)?.[key];
  return Array.isArray(candidate) &&
    candidate.every((item) => typeof item === "string")
    ? candidate
    : [];
};

const candidatesField = (value: JsonValue): readonly Candidate[] => {
  const candidates = asObject(value)?.["candidates"];
  return Array.isArray(candidates)
    ? (candidates as unknown as readonly Candidate[])
    : [];
};

const eventFromState = (value: JsonValue, name: string): Event => {
  if (value === null) throw new Error(`runtime state lacks ${name}`);
  return value as unknown as Event;
};

const workOrderFromValue = (value: JsonValue): WorkOrder => {
  if (value === null) throw new Error("runtime state lacks WorkOrder");
  return value as unknown as WorkOrder;
};

const cadenceFromCompiled = (compiled: CompiledProgram) => {
  const value = compiled.cadences[0];
  if (value === undefined) throw new Error("compiled loadout lacks cadence");
  return value;
};

const authorityFromState = (state: RuntimeState): AuthorityEnvelope =>
  state.authority as unknown as AuthorityEnvelope;

const revocationsFromState = (state: RuntimeState): readonly Event[] =>
  state.revocationEvents as unknown as readonly Event[];

const programFromState = (state: RuntimeState): Program.T => {
  if (state.program === null)
    throw new Error("runtime state lacks continuation");
  return state.program as unknown as Program.T;
};

const requiredContinuation = (decision: Decision<RuntimeState>): Program.T => {
  if (decision.continuation === undefined)
    throw new Error("kernel program decision lacks a continuation");
  return decision.continuation;
};

export const workOrderFromState = (state: RuntimeState): WorkOrder =>
  workOrderFromValue(state.workOrder);

export const commandFromState = (state: RuntimeState): Command => {
  if (state.pendingCommand === null)
    throw new Error("runtime state lacks pending command");
  return state.pendingCommand as unknown as Command;
};

const inspectIntent = (workOrder: WorkOrder): ActIntent => ({
  kind: "Act",
  effect: "repo.inspect",
  resource: "inspections",
  payload: { workOrder: workOrder as unknown as JsonValue },
});

const verificationProgram = (
  workOrder: WorkOrder,
  at: number,
  verificationSubject: string,
): Program.T => {
  const inspect = inspectIntent(workOrder);
  const id = commandId(WORKSTREAM, EPISODE, 1, 0);
  return Program.Invoke(id, inspect, {
    [verificationSubject]: Program.Emit(
      draft("VerificationRequested", at + 2, { commandId: id }),
      Program.Done(),
    ),
  });
};

const draft = (
  type: string,
  occurredAt: number,
  payload: JsonValue,
  correlationId?: string,
  causationId?: string,
): EventDraft => ({
  schemaVersion: 1,
  type,
  occurredAt,
  actorId: ACTOR,
  workstreamId: WORKSTREAM,
  episodeId: EPISODE,
  ...(correlationId === undefined ? {} : { correlationId }),
  ...(causationId === undefined ? {} : { causationId }),
  payload,
});

const linkedDraft = (
  event: EventDraft,
  correlationId: string | undefined,
  causationId: string,
): EventDraft => ({
  schemaVersion: event.schemaVersion,
  type: event.type,
  occurredAt: event.occurredAt,
  actorId: event.actorId,
  workstreamId: event.workstreamId,
  ...(event.episodeId === undefined ? {} : { episodeId: event.episodeId }),
  ...(correlationId === undefined ? {} : { correlationId }),
  causationId,
  payload: event.payload,
});

const observed = (
  state: RuntimeState,
  event: Event,
  branch = "observed",
): Decision<RuntimeState> => ({
  state,
  intents: [],
  schedules: [],
  trace: {
    reactorId: "seiri-reactor",
    reactorVersion: "1",
    branchPath: [event.type, branch],
    envInputs: ["event"],
    cadenceEvaluations: [],
  },
});

const workerNoOp = (
  state: RuntimeState,
  event: Event,
  reason: string,
): Decision<RuntimeState> => ({
  ...observed(state, event, reason),
  intents: [
    {
      kind: "NoOp",
      reason,
      evidence: [event.eventId],
      reevaluation: Cadence.Once(event.occurredAt),
      usefulWhen: { registryId: "operator.away", version: 1 },
    },
  ],
  trace: {
    reactorId: "worker-result-guard",
    reactorVersion: "1",
    branchPath: [event.type, "quarantine", reason],
    envInputs: [
      `now:${event.occurredAt}`,
      `authorityEnvelope:${stringField(state.authority, "authorityEnvelopeId") ?? "unavailable"}`,
    ],
    cadenceEvaluations: [],
  },
});

const workerResultGuard = (
  state: RuntimeState,
  event: Event,
  env: KernelEnv,
): Decision<RuntimeState> | undefined => {
  if (asObject(event.payload)?.["workerResultVersion"] !== 1)
    return workerNoOp(state, event, "invalid worker receipt");
  if (
    stringField(event.payload, "commandId") !==
    stringField(state.pendingCommand, "commandId")
  )
    return workerNoOp(state, event, "unknown command");
  if (state.commandResult !== null) return observed(state, event, "dedup");
  if (env.now >= authorityFromState(state).expiresAt)
    return workerNoOp(state, event, "authority expired");
  if (
    stringField(event.payload, "workerEpisodeId") !== state.workerEpisodeId ||
    state.workerLeaseExpired
  )
    return workerNoOp(state, event, "stale worker lease");
  if (state.presence !== "away")
    return workerNoOp(state, event, "operator returned");
  return undefined;
};

const pinnedIdentity = (state: RuntimeState): ArtifactIdentityV1 | null =>
  isArtifactIdentityV1(state.artifactIdentity) ? state.artifactIdentity : null;

const withIdentityTrace = (
  decision: Decision<RuntimeState>,
  identity: ArtifactIdentityV1 | null,
  equippedEventId: string | null,
): Decision<RuntimeState> =>
  identity === null || equippedEventId === null
    ? decision
    : {
        ...decision,
        trace: {
          ...decision.trace,
          envInputs: [
            ...new Set([
              ...decision.trace.envInputs,
              ...artifactIdentityInputs(identity, equippedEventId),
            ]),
          ],
        },
      };

const artifactRefused = (
  state: RuntimeState,
  event: Event,
  type: ArtifactRefusalType,
  reason: string,
  options: Readonly<{
    pinned?: ArtifactIdentityV1 | null;
    observed?: ArtifactIdentityV1 | null;
    diagnostics?: readonly CompileDiagnostic[];
    drift?: readonly ArtifactDriftField[];
  }> = {},
): Decision<RuntimeState> => {
  const pin = options.pinned ?? pinnedIdentity(state);
  return {
    state:
      type === "UnknownScheduleRefused"
        ? state
        : {
            ...state,
            artifactIdentityBlocked: true,
            authority: null,
            pendingCommand: null,
            program: null,
            activeScheduleIds: [],
          },
    intents: [],
    schedules: [],
    continuation: Program.Emit(
      {
        schemaVersion: 1,
        type,
        occurredAt: event.occurredAt,
        actorId: event.actorId,
        workstreamId: event.workstreamId,
        ...(event.episodeId === undefined
          ? {}
          : { episodeId: event.episodeId }),
        ...(event.correlationId === undefined
          ? {}
          : { correlationId: event.correlationId }),
        causationId: event.eventId,
        payload: artifactRefusalPayload(
          reason,
          event.eventId,
          state.equippedEventId,
          pin,
          options.observed ?? null,
          options.diagnostics ?? [],
          options.drift ?? [],
        ) as unknown as JsonValue,
      },
      Program.Done(),
    ),
    trace: {
      reactorId: "artifact-identity",
      reactorVersion: "1",
      branchPath: [event.type, "refused", type, reason],
      envInputs: [
        "event",
        "equipped-artifact",
        "logged-enforcement-boundary",
        ...(pin === null || state.equippedEventId === null
          ? []
          : artifactIdentityInputs(pin, state.equippedEventId)),
      ],
      cadenceEvaluations: [],
    },
  };
};

const equipDecision = (
  state: RuntimeState,
  event: Event,
): Decision<RuntimeState> => {
  const payload = asObject(event.payload);
  const legacy =
    payload === undefined || !Object.hasOwn(payload, "payloadVersion");
  if (
    legacy &&
    (state.identityEnforcementEventId !== null || state.artifactIdentityBlocked)
  )
    return artifactRefused(
      state,
      event,
      "ArtifactIdentityUnavailable",
      "legacy equip after enforcement boundary",
    );
  if (
    !legacy &&
    (payload?.["payloadVersion"] !== 2 ||
      Object.keys(payload).sort().join(",") !==
        "artifactIdentity,graph,payloadVersion" ||
      !isArtifactIdentityV1(payload["artifactIdentity"]))
  )
    return artifactRefused(
      state,
      event,
      "ArtifactIdentityInvalid",
      "invalid v2 equip payload",
    );
  const pin = legacy
    ? null
    : (payload!["artifactIdentity"] as unknown as ArtifactIdentityV1);
  const graph = legacy ? event.payload : payload!["graph"]!;
  const environment =
    pin === null ? seiriEnvironment() : pin.compilationEnvironment;
  const compiled = compileArtifact(graph, environment);
  if (!compiled.ok)
    return artifactRefused(
      state,
      event,
      "ArtifactCompilationRefused",
      "compile diagnostics",
      {
        pinned: pin,
        diagnostics: compiled.diagnostics,
      },
    );
  const drift =
    pin === null ? [] : artifactIdentityDrift(pin, compiled.artifactIdentity);
  if (drift.length > 0)
    return artifactRefused(
      state,
      event,
      "ArtifactIdentityDrift",
      "equipped artifact differs from compilation",
      {
        pinned: pin,
        observed: compiled.artifactIdentity,
        drift,
      },
    );
  return withIdentityTrace(
    observed(
      {
        ...state,
        loadout: graph,
        artifactIdentity: pin as unknown as JsonValue,
        compilationEnvironment: environment as unknown as JsonValue,
        equippedEventId: event.eventId,
        artifactIdentityBlocked: false,
        authority: compiled.program.authorityEnvelope as unknown as JsonValue,
        ...(legacy
          ? {}
          : {
              workOrder: null,
              pendingCommand: null,
              program: null,
              activeScheduleIds: [],
            }),
      },
      event,
      "equipped",
    ),
    pin,
    event.eventId,
  );
};

/** Every compiled consumer, including stored authority/continuations, enters here. */
const withEquippedArtifact = (
  state: RuntimeState,
  event: Event,
  consume: (compiled: CompiledProgram) => Decision<RuntimeState>,
): Decision<RuntimeState> => {
  const pin = pinnedIdentity(state);
  if (state.artifactIdentity !== null && pin === null)
    return artifactRefused(
      state,
      event,
      "ArtifactIdentityInvalid",
      "invalid stored artifact identity",
    );
  if (pin !== null && state.equippedEventId === null)
    return artifactRefused(
      state,
      event,
      "ArtifactIdentityInvalid",
      "pinned artifact has no equip event reference",
    );
  if (
    state.loadout === null ||
    state.artifactIdentityBlocked ||
    (state.identityEnforcementEventId !== null && pin === null)
  )
    return artifactRefused(
      state,
      event,
      "ArtifactIdentityUnavailable",
      state.loadout === null
        ? "no valid equip"
        : "explicit v2 re-equip required",
    );
  const compiled = compileArtifact(state.loadout, state.compilationEnvironment);
  if (!compiled.ok)
    return artifactRefused(
      state,
      event,
      "ArtifactCompilationRefused",
      "compile diagnostics",
      {
        diagnostics: compiled.diagnostics,
      },
    );
  const drift =
    pin === null ? [] : artifactIdentityDrift(pin, compiled.artifactIdentity);
  if (drift.length > 0)
    return artifactRefused(
      state,
      event,
      "ArtifactIdentityDrift",
      "pinned artifact differs from compilation",
      {
        observed: compiled.artifactIdentity,
        drift,
      },
    );
  return withIdentityTrace(
    consume(compiled.program),
    pin,
    state.equippedEventId,
  );
};

const predicateEnv = (env: KernelEnv): Omit<KernelEnv, "now"> => ({
  rngState: env.rngState,
  predicates: env.predicates,
  ...(env.policy === undefined ? {} : { policy: env.policy }),
});

const presenceDecision = (
  state: RuntimeState,
  event: Event,
  env: KernelEnv,
  compiled: CompiledProgram,
): Decision<RuntimeState> => {
  const presence = stringField(event.payload, "presence");
  if (presence !== "away" && presence !== "returned")
    return observed(state, event, "invalid-presence");

  const nextState: RuntimeState = {
    ...state,
    presence,
    revocationEvents: [
      ...state.revocationEvents,
      event as unknown as JsonValue,
    ],
  };
  if (presence === "away") {
    const compiledCadence = cadenceFromCompiled(compiled);
    const cadence = compiledCadence.cadence as Cadence.T;
    const evaluated = evaluateCadence(cadence, nextState, env, event);
    if (evaluated.dueAt === null)
      throw new Error("away cadence did not produce a pulse");
    const schedules = [
      {
        scheduleId: compiledCadence.scheduleId,
        cadence,
        eventToEmit: draft(
          "CadencePulse",
          evaluated.dueAt,
          {
            scheduleId: compiledCadence.scheduleId,
          },
          undefined,
          event.eventId,
        ),
        cancelOn: compiledCadence.cancelOn,
      },
      {
        scheduleId: compiledCadence.queuedScheduleId,
        cadence: Cadence.Once(evaluated.dueAt + compiledCadence.queuedDelayMs),
        eventToEmit: draft(
          "CadencePulse",
          evaluated.dueAt + compiledCadence.queuedDelayMs,
          {
            scheduleId: compiledCadence.queuedScheduleId,
          },
          undefined,
          event.eventId,
        ),
        cancelOn: compiledCadence.cancelOn,
      },
    ] as const;
    return {
      state: {
        ...nextState,
        rngState: evaluated.rngState,
        activeScheduleIds: schedules.map((schedule) => schedule.scheduleId),
      },
      intents: [],
      schedules,
      trace: {
        reactorId: "seiri-cadence",
        reactorVersion: "1",
        branchPath: ["away", "scheduled"],
        envInputs: ["operatorPresence", "virtualTime"],
        cadenceEvaluations: [evaluated.trace],
      },
    };
  }

  const workOrder = workOrderFromState(nextState);
  const revoked = authorize(
    inspectIntent(workOrder),
    authorityFromState(state),
    {
      now: env.now,
      actorId: ACTOR,
      workstreamId: WORKSTREAM,
      episodeId: EPISODE,
      decisionIndex: 3,
      intentIndex: 0,
      evidence: [],
      revokedBy: revocationsFromState(nextState),
      state: nextState,
      predicateEnv: predicateEnv(env),
    },
  );
  if (
    revoked.authorized ||
    revoked.refusal.payload.reason !== "authority revoked"
  )
    throw new Error("operator return did not revoke inspect authority");
  return {
    state: nextState,
    intents: [],
    schedules: [],
    trace: revoked.trace,
  };
};

const pulseDecision = (
  state: RuntimeState,
  event: Event,
  env: KernelEnv,
  compiled: CompiledProgram,
): Decision<RuntimeState> => {
  const scheduleId = stringField(event.payload, "scheduleId");
  const compiledCadence = cadenceFromCompiled(compiled);
  if (scheduleId === compiledCadence.scheduleId) {
    const workOrder = compiled.workOrder;
    return {
      ...observed(
        {
          ...state,
          pulseSeen: true,
          workOrder: workOrder as unknown as JsonValue,
        },
        event,
        "work-order-ready",
      ),
      continuation: Program.Emit(
        draft(
          "WorkOrderEmitted",
          event.occurredAt,
          { workOrder: workOrder as unknown as JsonValue },
          event.eventId,
          event.eventId,
        ),
        Program.Done(),
      ),
    };
  }
  if (scheduleId !== compiledCadence.queuedScheduleId) {
    if (
      state.identityEnforcementEventId === null &&
      state.artifactIdentity === null
    )
      return observed(state, event, "unknown-schedule");
    return artifactRefused(
      state,
      event,
      "UnknownScheduleRefused",
      `unknown schedule: ${scheduleId ?? "unavailable"}`,
    );
  }

  const activationCondition = compiled.statechartGuards[0]?.activationCondition;
  if (activationCondition === undefined)
    throw new Error("compiled loadout lacks an activation guard");
  const guarded = guardQueuedPulse(state, event, env, activationCondition, [
    compiledCadence.scheduleId,
    compiledCadence.queuedScheduleId,
  ]);
  return {
    state: {
      ...state,
      cancelledScheduleIds: guarded.cancelledScheduleIds,
    },
    intents: guarded.intents,
    schedules: guarded.schedules,
    trace: guarded.trace,
  };
};

const workOrderDecision = (
  state: RuntimeState,
  event: Event,
  env: KernelEnv,
  compiled: CompiledProgram,
): Decision<RuntimeState> => {
  const workOrder = workOrderFromValue(
    asObject(event.payload)?.["workOrder"] ?? null,
  );
  const verification = compiled.verificationPlan.find(
    (episode) => episode.required,
  );
  if (verification === undefined)
    throw new Error("compiled loadout lacks a required verification episode");
  const program = verificationProgram(
    workOrder,
    event.occurredAt,
    verification.subject,
  );
  const programDecision = decideProgram(program, state, env);
  const continuation = requiredContinuation(programDecision);
  const inspect = programDecision.intents[0];
  if (inspect?.kind !== "Act")
    throw new Error("verification program did not produce an inspect intent");
  const granted = authorize(inspect, authorityFromState(state), {
    now: env.now,
    actorId: ACTOR,
    workstreamId: WORKSTREAM,
    episodeId: EPISODE,
    decisionIndex: 1,
    intentIndex: 0,
    evidence: [],
    revokedBy: revocationsFromState(state),
    state,
    predicateEnv: predicateEnv(env),
  });
  if (!granted.authorized)
    throw new Error(
      `inspection authorization failed: ${granted.refusal.payload.reason}`,
    );
  return {
    state: {
      ...state,
      workOrder: workOrder as unknown as JsonValue,
      authority: granted.authority as unknown as JsonValue,
      pendingCommand: granted.command as unknown as JsonValue,
      program: continuation as unknown as JsonValue,
    },
    intents: programDecision.intents,
    continuation,
    schedules: programDecision.schedules,
    trace: granted.trace,
  };
};

const deletionDecision = (
  state: RuntimeState,
  event: Event,
  env: KernelEnv,
): Decision<RuntimeState> => {
  const effect = stringField(event.payload, "effect") ?? "";
  const paths = stringArrayField(event.payload, "paths");
  const evidence = state.candidates.flatMap((candidate) => candidate.evidence);
  const deletion: ActIntent = { kind: "Act", effect, payload: { paths } };
  const refused = authorize(deletion, authorityFromState(state), {
    now: env.now,
    actorId: ACTOR,
    workstreamId: WORKSTREAM,
    episodeId: EPISODE,
    decisionIndex: 2,
    intentIndex: 0,
    evidence,
    revokedBy: revocationsFromState(state),
    state,
    predicateEnv: predicateEnv(env),
  });
  if (refused.authorized) throw new Error("deletion unexpectedly authorized");
  return {
    state: {
      ...state,
      authorizationEvidence: evidence,
      deletionPaths: paths,
      refusalReason: refused.refusal.payload.reason,
    },
    intents: [],
    continuation: Program.Emit(
      linkedDraft(refused.refusal, expectedInspectCommandId, event.eventId),
      Program.Done(),
    ),
    schedules: [],
    trace: refused.trace,
  };
};

const episodeDecision = (
  state: RuntimeState,
  event: Event,
  env: KernelEnv,
): Decision<RuntimeState> => {
  const result = eventFromState(state.commandResult, "CommandResult");
  const continued = decideProgram(
    programFromState(state),
    state,
    { ...env, now: result.occurredAt },
    result,
  );
  const continuation = requiredContinuation(continued);
  if (continuation.kind !== "Emit")
    throw new Error("verification continuation did not emit a request");
  const linkedContinuation = Program.Emit(
    linkedDraft(continuation.event, expectedInspectCommandId, event.eventId),
    continuation.next,
  );
  return {
    state: {
      ...state,
      program: linkedContinuation as unknown as JsonValue,
    },
    intents: continued.intents,
    continuation: linkedContinuation,
    schedules: continued.schedules,
    trace: continued.trace,
  };
};

const beaconSweepDecision = (
  state: RuntimeState,
  event: Event,
  env: KernelEnv,
): Decision<RuntimeState> => {
  const request = event.payload as unknown as BeaconSweepRequest & {
    decisionIndex: number;
    perceptionVersion?: number;
    perception?: PerceptionDeclaration;
    perceptionError?: string | null;
  };
  if (
    request.intent?.kind !== "Observe" ||
    request.intent.subject !== "control-beacons" ||
    !["public", "verifier"].includes(request.audience) ||
    !Number.isSafeInteger(request.staleAfterMs) ||
    request.staleAfterMs < 0 ||
    !Number.isSafeInteger(request.decisionIndex) ||
    request.decisionIndex < 0
  )
    throw new Error("invalid Beacon sweep request");
  const effect: ActIntent = {
    kind: "Act",
    effect: `observe.beacons.${request.audience}`,
    resource: "beaconSweeps",
    payload: { subject: request.intent.subject, audience: request.audience },
  };
  // Observation values are deliberately absent from this authority context.
  let authorization: AuthorizationResult = authorize(
    effect,
    request.authority,
    {
      now: env.now,
      actorId: event.actorId,
      workstreamId: event.workstreamId,
      ...(event.episodeId ? { episodeId: event.episodeId } : {}),
      decisionIndex: request.decisionIndex,
      intentIndex: 0,
      evidence: request.evidence,
      revokedBy: request.revokedBy,
      state: { presence: state.presence, policy: state.policy },
      predicateEnv: predicateEnv(env),
    },
  );
  if (authorization.authorized && request.perceptionVersion !== undefined) {
    const reason =
      request.perceptionVersion !== 1 || !request.perception
        ? "invalid Beacon perception version"
        : (request.perceptionError ??
          perceptionGate(
            request.perception,
            request.authority,
            request.audience,
          ));
    if (reason)
      authorization = refusePerception(event, request.authority, reason);
  }
  return {
    state: {
      ...state,
      beaconSweep: {
        requestEventId: event.eventId,
        staleAfterMs: request.staleAfterMs,
        authorization: authorization as unknown as JsonValue,
        ...(request.perceptionVersion === undefined
          ? {}
          : { perception: request.perception as unknown as JsonValue }),
      },
    },
    intents: authorization.authorized ? [request.intent] : [],
    schedules: [],
    trace: authorization.trace,
  };
};

const beaconObservedDecision = (
  state: RuntimeState,
  event: Event,
  env: KernelEnv,
): Decision<RuntimeState> => {
  const payload = event.payload as unknown as {
    sweptAt: number;
    observations: readonly SignalObservation[];
    commandId: string;
    groups?: PerceptionRead["groups"];
    keyEpoch?: number | null;
    perceptionVersion?: number;
  };
  const sweep = state.beaconSweep as unknown as {
    staleAfterMs: number;
    authorization: { authorized: boolean; command?: Command };
    perception?: PerceptionDeclaration;
  } | null;
  if (
    !sweep?.authorization.authorized ||
    payload.commandId !== sweep.authorization.command?.commandId ||
    payload.sweptAt !== event.occurredAt ||
    payload.sweptAt !== env.now ||
    !Array.isArray(payload.observations)
  )
    throw new Error("BeaconObserved lacks its authorized sweep or event time");
  if (sweep.perception) {
    if (
      payload.perceptionVersion !== 1 ||
      payload.groups === undefined ||
      payload.keyEpoch === undefined
    )
      throw new Error("BeaconObserved lacks its sense projection version");
    validatePerception(
      { observations: payload.observations, groups: payload.groups },
      sweep.perception,
      payload.keyEpoch,
    );
  }
  const cadenceEvaluations: string[] = [];
  const observations = payload.observations.map((observation): JudgedBeacon => {
    // Persist decoded perception, but bind it to the captured size on replay.
    const decoded =
      observation.size === null
        ? { status: "absent" }
        : (sweep.perception ? decodeSignalSize : decodeLegacySignalSize)(
            BigInt(observation.size),
          );
    if (canonicalStringify(decoded) !== canonicalStringify(observation.decoded))
      throw new Error(
        "BeaconObserved decoded fields differ from captured metadata",
      );
    let age = beaconAge(observation, env.now, sweep.staleAfterMs);
    if (age === "fresh" || age === "stale") {
      // The kernel clock is integer milliseconds: round the captured origin up
      // so a sub-ms remainder cannot fire the After cadence prematurely.
      const origin =
        observation.mtimeNs == null
          ? observation.mtimeMs!
          : Number((BigInt(observation.mtimeNs) + 999999n) / 1000000n);
      const evaluated = evaluateCadence(
        Cadence.After(sweep.staleAfterMs),
        state,
        { ...env, now: origin },
        event,
      );
      cadenceEvaluations.push(evaluated.trace);
      age =
        evaluated.dueAt !== null && env.now >= evaluated.dueAt
          ? "stale"
          : "fresh";
    }
    return { ...observation, age };
  });
  return {
    state: {
      ...state,
      beaconObservations: observations,
      ...(sweep.perception
        ? { beaconGroups: payload.groups as unknown as JsonValue }
        : {}),
    },
    intents: [],
    schedules: [],
    trace: {
      reactorId: "beacon-observer",
      reactorVersion: "1",
      branchPath: ["BeaconObserved", ...observations.map(({ age }) => age)],
      envInputs: ["event.payload.observations", "event.occurredAt"],
      cadenceEvaluations,
    },
  };
};

const react = (
  state: RuntimeState,
  event: Event,
  env: KernelEnv,
  compiled?: CompiledProgram,
): Decision<RuntimeState> => {
  switch (event.type) {
    case "BeaconSweepRequested":
      return beaconSweepDecision(state, event, env);
    case "BeaconObserved":
      return beaconObservedDecision(state, event, env);
    case "InspectionTaskCreated":
      return observed(state, event, "task-opened");
    case "OperatorPresenceChanged":
      return presenceDecision(state, event, env, compiled!);
    case "CadencePulse":
      return pulseDecision(state, event, env, compiled!);
    case "WorkOrderEmitted":
      return workOrderDecision(state, event, env, compiled!);
    case "CommandRedispatchRequested":
      if (
        stringField(event.payload, "commandId") === undefined ||
        stringField(event.payload, "commandId") !==
          stringField(state.pendingCommand, "commandId")
      )
        return artifactRefused(
          state,
          event,
          "ArtifactIdentityInvalid",
          "recovery request does not name the stored command",
        );
      if (
        asObject(event.payload)?.["workerDispatchVersion"] === 1 &&
        (env.now >= authorityFromState(state).expiresAt ||
          state.presence !== "away")
      )
        return workerNoOp(
          state,
          event,
          env.now >= authorityFromState(state).expiresAt
            ? "authority expired"
            : "operator returned",
        );
      return observed(state, event, "redispatch-ready");
    case "WorkerAttemptStarted":
      return observed(
        {
          ...state,
          workerEpisodeId:
            stringField(event.payload, "workerEpisodeId") ?? null,
          workerLeaseExpired: false,
        },
        event,
      );
    case "WorkerLeaseExpired":
      return stringField(event.payload, "workerEpisodeId") ===
        state.workerEpisodeId
        ? observed({ ...state, workerLeaseExpired: true }, event)
        : observed(state, event, "stale-lease");
    case "CommandPersisted": {
      const command = asObject(event.payload)?.["command"] ?? null;
      const effect =
        command === null
          ? undefined
          : stringField(asObject(command)?.["intent"] ?? null, "effect");
      if (effect?.startsWith("observe.beacons."))
        return observed(state, event, "beacon-sweep-durable");
      return observed(
        {
          ...state,
          pendingCommand: command,
          persistedEffect: effect ?? null,
        },
        event,
        "command-durable",
      );
    }
    case "CommandRedispatched": {
      const commandId = stringField(event.payload, "commandId");
      return observed(
        {
          ...state,
          redispatchedCommandIds:
            commandId === undefined
              ? state.redispatchedCommandIds
              : [...state.redispatchedCommandIds, commandId],
        },
        event,
        "command-redispatched",
      );
    }
    case "WorkerResultObserved":
      return (
        workerResultGuard(state, event, env) ??
        observed(state, event, "worker-result-admissible")
      );
    case "CommandResult": {
      if (event.workstreamId === "ws_beacon_control")
        return observed(state, event, "beacon-sweep-returned");
      if (asObject(event.payload)?.["workerResultVersion"] === 1) {
        const refusal = workerResultGuard(state, event, env);
        if (refusal) return refusal;
      }
      const candidates = candidatesField(event.payload);
      const deletion: ActIntent = {
        kind: "Act",
        effect: "repo.delete",
        payload: { paths: candidates.map((candidate) => candidate.path) },
      };
      return {
        state: {
          ...state,
          candidates,
          commandResult: event as unknown as JsonValue,
          inspectionCompleted: true,
          deletionPaths: candidates.map((candidate) => candidate.path),
        },
        intents: [deletion],
        schedules: [],
        trace: {
          reactorId: "seiri-reactor",
          reactorVersion: "1",
          branchPath: ["CommandResult", "deletion-proposed"],
          envInputs: ["event.payload.candidates"],
          cadenceEvaluations: [],
        },
      };
    }
    case "DeletionAttempted":
      return deletionDecision(state, event, env);
    case "CommandRefused":
      if (event.workstreamId === "ws_beacon_control")
        return observed(state, event, "beacon-sweep-refused");
      return {
        ...observed(
          {
            ...state,
            deletionRefused: true,
            refusalReason: stringField(event.payload, "reason") ?? null,
          },
          event,
          "episode-terminating",
        ),
        continuation: Program.Emit(
          draft(
            "EpisodeTerminated",
            event.occurredAt + 1,
            {
              continuation: "verification",
            },
            expectedInspectCommandId,
            event.eventId,
          ),
          Program.Done(),
        ),
      };
    case "EpisodeTerminated":
      return episodeDecision(state, event, env);
    case "VerificationRequested":
      return {
        ...observed(state, event, "verification-dispatched"),
        intents: [{ kind: "Observe", subject: "candidates" }],
      };
    case "VerificationCompleted":
      return observed(
        {
          ...state,
          verified: asObject(event.payload)?.["accepted"] === true,
          verificationCompleted: true,
        },
        event,
        "verification-folded",
      );
    case "QueuedPulseNoOp":
      return observed(
        {
          ...state,
          queuedPulseNoOp: true,
          noOpEvidence: stringArrayField(event.payload, "evidence"),
        },
        event,
        "no-op-folded",
      );
    case "SchedulesCancelled":
      return observed(
        {
          ...state,
          cancelledScheduleIds: stringArrayField(event.payload, "scheduleIds"),
          activeScheduleIds: stringArrayField(
            event.payload,
            "activeScheduleIds",
          ),
        },
        event,
        "cancellation-folded",
      );
    default:
      return observed(state, event);
  }
};

export const seiriReactor: Reactor<RuntimeState> = (state, event, env) => {
  if (event.type === "FeedbackAuditOpened" || state.feedback !== undefined)
    return feedbackDecision(state, event);
  if (state.verification !== undefined)
    return verificationDecision(state, event);

  if (event.type === "ArtifactIdentityEnforcementStarted") {
    if (canonicalStringify(event.payload) !== '{"payloadVersion":1}')
      return artifactRefused(
        state,
        event,
        "ArtifactIdentityInvalid",
        "invalid enforcement boundary",
      );
    if (state.identityEnforcementEventId !== null)
      return observed(state, event, "already-enforced");
    return observed(
      {
        ...state,
        identityEnforcementEventId: event.eventId,
        ...(pinnedIdentity(state) === null
          ? { authority: null, pendingCommand: null, program: null }
          : {}),
      },
      event,
      "enforcement-started",
    );
  }
  if (event.type === "LoadoutEquipped") return equipDecision(state, event);
  if (isArtifactRefusalType(event.type))
    return observed(
      event.type === "UnknownScheduleRefused"
        ? state
        : {
            ...state,
            artifactIdentityBlocked: true,
            authority: null,
            pendingCommand: null,
            program: null,
            activeScheduleIds: [],
          },
      event,
      "refusal-recorded",
    );
  // Beacon authority is supplied by its explicit host request, not this loadout.
  const beaconResult =
    event.workstreamId === "ws_beacon_control" &&
    (event.type === "CommandResult" || event.type === "CommandRefused");
  const consumesProgram =
    !beaconResult &&
    [
      "OperatorPresenceChanged",
      "CadencePulse",
      "WorkOrderEmitted",
      "CommandResult",
      "WorkerResultObserved",
      "DeletionAttempted",
      "CommandRefused",
      "EpisodeTerminated",
      "VerificationRequested",
      "CommandRedispatchRequested",
    ].includes(event.type);
  return consumesProgram
    ? withEquippedArtifact(state, event, (compiled) =>
        react(state, event, env, compiled),
      )
    : react(state, event, env);
};

export const expectedInspectCommandId = commandId(WORKSTREAM, EPISODE, 1, 0);

// Independent-verification workstreams use the same typed reactor boundary.
export const VERIFICATION_HOST = "verification-host";
export interface MatrixEvaluation extends Evaluation {
  readonly provenance: {
    readonly kind: "host-admitted-verifier";
    readonly commandId: string;
    readonly inputHash: string;
  };
  readonly eventId: string;
  readonly episodeId: string;
  readonly subjectRevision: string;
  readonly stale: boolean;
}
export interface AcceptanceEvidenceRow {
  readonly criterion: AcceptanceCriterion;
  readonly status: "incomplete" | "verified" | "failed" | "stale";
  readonly evaluations: readonly MatrixEvaluation[];
}
export interface FindingRecord {
  readonly finding: VerificationFinding;
  readonly eventId: string;
  readonly episodeId: string;
  readonly subjectRevision: string;
  readonly status: "open" | "resolved" | "superseded";
}
export interface VerificationPending {
  readonly capsule: VerificationTask;
  readonly command: Command;
  readonly ordinal: number;
  readonly persisted: boolean;
  readonly attempts: readonly string[];
  readonly activeEpisode: string | null;
  readonly leaseExpiresAt: number;
  readonly leaseExpired: boolean;
}
export interface VerificationState {
  readonly workstreamId: string;
  readonly criteria: readonly AcceptanceCriterion[];
  readonly baseline: VerificationSubject | null;
  readonly subject: VerificationSubject | null;
  readonly rows: readonly AcceptanceEvidenceRow[];
  readonly evidence: readonly VerificationEvidence[];
  readonly findings: readonly FindingRecord[];
  readonly repairPlans: readonly {
    readonly findingId: string;
    readonly capsule: VerificationTask;
  }[];
  readonly implementerEpisodes: readonly string[];
  readonly episodeIds: readonly string[];
  readonly authority: AuthorityEnvelope | null;
  readonly revocations: readonly Event[];
  readonly pending: VerificationPending | null;
  readonly continuation: Program.T;
  readonly next:
    | "unopened"
    | "verify"
    | "repair"
    | "apply-repair"
    | "complete"
    | "attention";
  readonly proposal: RepairWorkerResult | null;
  readonly dispatchCount: number;
  readonly repairCount: number;
  readonly maxRepairs: number;
  readonly lastResultEventId: string | null;
  readonly refusedResults: readonly string[];
  readonly staleness: readonly {
    readonly eventId: string;
    readonly changedSurfaces: readonly string[];
    readonly criterionIds: readonly string[];
  }[];
}
export const initialVerificationState = (
  workstreamId: string,
): VerificationState => ({
  workstreamId,
  criteria: [],
  baseline: null,
  subject: null,
  rows: [],
  evidence: [],
  findings: [],
  repairPlans: [],
  implementerEpisodes: [],
  episodeIds: [],
  authority: null,
  revocations: [],
  pending: null,
  continuation: Program.Done(),
  next: "unopened",
  proposal: null,
  dispatchCount: 0,
  repairCount: 0,
  maxRepairs: 3,
  lastResultEventId: null,
  refusedResults: [],
  staleness: [],
});
const json = (value: unknown): JsonValue => value as JsonValue;
const env = (now: number) => ({ now, rngState: 17, predicates: {} });
const same = (a: unknown, b: unknown): boolean =>
  canonicalStringify(a) === canonicalStringify(b);
const requireState = (value: unknown, detail: string): void => {
  if (!value) throw new Error(`verification state: ${detail}`);
};
// EventEnvelope is deliberately open. Each branch checks the fields it consumes;
// model results cross the stricter, closed schema in parseEvidenceResult.
type VerificationPayload = {
  criteria: readonly AcceptanceCriterion[];
  baseline: VerificationSubject;
  subject: VerificationSubject;
  implementerEpisodeId: string;
  maxRepairs: number;
  authority: AuthorityEnvelope;
  command: Command;
  commandId: string;
  workerEpisodeId: string;
  role: VerificationTask["role"];
  inputHash: string;
  leaseExpiresAt: number;
  mode: string;
  verificationResultVersion: number;
  result: string;
  value: EvidenceWorkerResult;
};

export function verificationAuthorization(
  state: VerificationState,
  at: number,
) {
  const pending = state.pending;
  if (!pending || !state.authority)
    throw new Error("verification lacks a pending authorized command");
  return authorize(pending.command.intent, state.authority, {
    now: at,
    actorId: VERIFICATION_HOST,
    workstreamId: state.workstreamId,
    episodeId: pending.command.episodeId!,
    decisionIndex: pending.ordinal,
    intentIndex: 0,
    evidence: ["pinned-subject", "baseline-witness"],
    revokedBy: state.revocations,
  });
}

/** The one-shot planning host shares the skeleton's authority decider owner. */
export function planRefutationAuthorization(
  authority: AuthorityEnvelope,
  subjectHash: string,
  episodeId: string,
  phase: "read" | "report",
  at: number,
) {
  return authorize(
    phase === "read"
      ? {
          kind: "Act",
          effect: "repo.read.plan-subject",
          payload: { subjectHash },
        }
      : { kind: "Act", effect: "report.emit", payload: {} },
    authority,
    {
      now: at,
      actorId: "entropy-reducer",
      workstreamId: "ws_plan_refuter",
      episodeId,
      decisionIndex: 0,
      intentIndex: phase === "read" ? 0 : 1,
      evidence: [],
      revokedBy: [],
    },
  );
}

/** Harness adapters share the skeleton's authority decider owner. */
export function harnessAuthorization(
  authority: AuthorityEnvelope,
  effect: string,
  at: number,
) {
  return authorize({ kind: "Act", effect, payload: {} }, authority, {
    now: at,
    actorId: "contributor-hook",
    workstreamId: "contributor-session",
    decisionIndex: 0,
    intentIndex: 0,
    evidence: ["resolved-worktree"],
    revokedBy: [],
  });
}

function dispatch(state: VerificationState): VerificationState {
  requireState(
    !state.pending &&
      state.subject &&
      state.continuation.kind === "Done" &&
      ["verify", "repair"].includes(state.next),
    "dispatch phase",
  );
  const ordinal = state.dispatchCount + 1;
  const finding =
    state.next === "repair"
      ? (state.findings.find(
          (record) =>
            record.status === "open" && record.finding.severity === "blocking",
        )?.finding ?? null)
      : null;
  requireState(state.next !== "repair" || finding, "repair finding");
  const criteria = finding
    ? state.criteria.filter(
        (criterion) => criterion.criterionId === finding.criterionId,
      )
    : state.rows
        .filter((row) => row.status !== "verified")
        .map((row) => row.criterion);
  const capsule = compileVerificationTask(
    `verification_${ordinal}`,
    criteria,
    state.subject!,
    finding,
  );
  const episodeId = `ep_${capsule.role}_${ordinal}`;
  const command: Command = {
    commandId: commandId(state.workstreamId, episodeId, ordinal, 0),
    episodeId,
    workstreamId: state.workstreamId,
    intent: {
      kind: "Act",
      effect: capsule.workOrder.allowedOperations[0]!,
      resource: "episodes",
      payload: json({ capsule }),
    },
  };
  const continuation = Program.Invoke(command.commandId, command.intent, {
    completed: Program.Emit(
      {
        schemaVersion: 1,
        type: "VerificationContinuation",
        actorId: VERIFICATION_HOST,
        workstreamId: state.workstreamId,
        occurredAt: 0,
        correlationId: command.commandId,
        payload: { commandId: command.commandId },
      },
      Program.Done(),
    ),
  });
  // The kernel emits the dispatch intent. The host persists it before invoking a transport.
  const decision = decideProgram(continuation, json(state), env(0));
  requireState(decision.intents.length === 1, "kernel dispatch intent");
  return {
    ...state,
    dispatchCount: ordinal,
    continuation,
    pending: {
      capsule,
      command,
      ordinal,
      persisted: false,
      attempts: [],
      activeEpisode: null,
      leaseExpiresAt: 0,
      leaseExpired: false,
    },
  };
}

/** Pure event-loop fold. Worker prose and implementer events have no acceptance path. */
function foldVerificationEvent(
  state: VerificationState,
  event: Event,
): VerificationState {
  if (event.workstreamId !== state.workstreamId) return state;
  if (state.authority?.revocationEventTypes.includes(event.type))
    return { ...state, revocations: [...state.revocations, event] };
  if (event.actorId !== VERIFICATION_HOST) return state;
  const value = event.payload as unknown as VerificationPayload;
  switch (event.type) {
    case "VerificationOpened": {
      requireState(state.next === "unopened", "workstream already opened");
      const criteria = (value.criteria as AcceptanceCriterion[]).map(
        copyCriterion,
      );
      const baseline = copySubject(value.baseline as VerificationSubject);
      const subject = copySubject(value.subject as VerificationSubject);
      compileVerificationTask("opening", criteria, subject);
      requireState(
        baseline.repo === subject.repo &&
          baseline.baseCommit === subject.baseCommit &&
          baseline.revision === subject.baseCommit,
        "baseline identity",
      );
      requireState(
        typeof value.implementerEpisodeId === "string" &&
          value.implementerEpisodeId.length > 0 &&
          Number.isSafeInteger(value.maxRepairs) &&
          value.maxRepairs >= 0 &&
          value.maxRepairs <= 10,
        "opening policy",
      );
      requireState(
        baseline.evidence.length > 0 &&
          criteria.every((criterion) =>
            baseline.evidence.some(
              (item) => item.criterionId === criterion.criterionId,
            ),
          ),
        "baseline witness coverage",
      );
      return {
        ...state,
        criteria,
        baseline,
        subject,
        authority: value.authority as AuthorityEnvelope,
        maxRepairs: value.maxRepairs,
        implementerEpisodes: [value.implementerEpisodeId],
        episodeIds: [value.implementerEpisodeId],
        rows: criteria.map((criterion) => ({
          criterion,
          status: "incomplete",
          evaluations: [],
        })),
        evidence: subject.evidence,
        next: "verify",
      };
    }
    case "VerificationDispatchRequested":
      return dispatch(state);
    case "CommandPersisted": {
      const pending = state.pending;
      if (!pending || value.command?.commandId !== pending.command.commandId)
        return state;
      requireState(
        same(value.command, pending.command),
        "persisted compilation drift",
      );
      requireState(
        verificationAuthorization(state, event.occurredAt).authorized,
        "persist without authority",
      );
      return { ...state, pending: { ...pending, persisted: true } };
    }
    case "WorkerAttemptStarted": {
      const pending = state.pending;
      if (
        !pending ||
        !pending.persisted ||
        value.commandId !== pending.command.commandId
      )
        return state;
      requireState(
        !state.episodeIds.includes(value.workerEpisodeId) &&
          typeof value.workerEpisodeId === "string" &&
          value.role === pending.capsule.role &&
          value.inputHash === pending.capsule.inputHash &&
          typeof value.leaseExpiresAt === "number" &&
          value.leaseExpiresAt > event.occurredAt,
        "fresh physical episode",
      );
      requireState(
        pending.activeEpisode === null ||
          pending.leaseExpired ||
          event.occurredAt >= pending.leaseExpiresAt ||
          value.mode === "cached-result-query",
        "prior episode still leased",
      );
      return {
        ...state,
        episodeIds: [...state.episodeIds, value.workerEpisodeId],
        pending: {
          ...pending,
          attempts: [...pending.attempts, value.workerEpisodeId],
          activeEpisode: value.workerEpisodeId,
          leaseExpiresAt: value.leaseExpiresAt,
          leaseExpired: false,
        },
      };
    }
    case "WorkerHeartbeat": {
      const pending = state.pending;
      if (
        !pending ||
        value.workerEpisodeId !== pending.activeEpisode ||
        pending.leaseExpired ||
        event.occurredAt >= pending.leaseExpiresAt
      )
        return state;
      return {
        ...state,
        pending: { ...pending, leaseExpiresAt: value.leaseExpiresAt },
      };
    }
    case "WorkerLeaseExpired": {
      const pending = state.pending;
      if (
        !pending ||
        value.workerEpisodeId !== pending.activeEpisode ||
        event.occurredAt < pending.leaseExpiresAt
      )
        return state;
      return { ...state, pending: { ...pending, leaseExpired: true } };
    }
    case "CommandResult": {
      const pending = state.pending;
      if (
        !pending ||
        !pending.persisted ||
        value.commandId !== pending.command.commandId ||
        value.verificationResultVersion !== 1
      )
        return state;
      let result: EvidenceWorkerResult;
      try {
        requireState(
          value.workerEpisodeId === pending.activeEpisode &&
            !pending.leaseExpired &&
            event.occurredAt < pending.leaseExpiresAt &&
            pending.attempts.includes(value.value?.envelope?.episodeId) &&
            !state.implementerEpisodes.includes(
              value.value?.envelope?.episodeId,
            ),
          "result episode or lease",
        );
        requireState(
          verificationAuthorization(state, event.occurredAt).authorized,
          "result authority",
        );
        assertVerificationTask(pending.capsule);
        requireState(
          pending.capsule.subject.revision === state.subject?.revision,
          "result subject drift",
        );
        result = parseEvidenceResult(value.value, {
          command: pending.command,
          workOrder: pending.capsule.workOrder,
          capsule: pending.capsule,
          episodeId: value.value.envelope.episodeId,
        });
        requireState(
          result.envelope.status === "completed" &&
            value.result === "completed",
          "incomplete result",
        );
      } catch {
        return {
          ...state,
          refusedResults: [...state.refusedResults, event.eventId],
        };
      }
      const step = decideProgram(
        state.continuation,
        json(state),
        env(event.occurredAt),
        event,
      );
      requireState(step.continuation?.kind === "Emit", "result continuation");
      const common = {
        ...state,
        pending: null,
        lastResultEventId: event.eventId,
        continuation: step.continuation!,
      };
      if (result.kind === "repair")
        return {
          ...common,
          next: result.envelope.requiresHuman ? "attention" : "apply-repair",
          proposal: result,
        };
      const rows = state.rows.map((row): AcceptanceEvidenceRow => {
        const evaluation = result.evaluations.find(
          (item) => item.criterionId === row.criterion.criterionId,
        );
        return evaluation
          ? {
              criterion: row.criterion,
              status:
                evaluation.verdict === "pass"
                  ? "verified"
                  : evaluation.verdict === "fail"
                    ? "failed"
                    : "incomplete",
              evaluations: [
                ...row.evaluations,
                {
                  ...evaluation,
                  provenance: {
                    kind: "host-admitted-verifier",
                    commandId: pending.command.commandId,
                    inputHash: pending.capsule.inputHash,
                  },
                  eventId: event.eventId,
                  episodeId: result.envelope.episodeId,
                  subjectRevision: result.subjectRevision,
                  stale: false,
                },
              ],
            }
          : row;
      });
      const findingRecords: FindingRecord[] = result.findings.map(
        (finding) => ({
          finding,
          eventId: event.eventId,
          episodeId: result.envelope.episodeId,
          subjectRevision: result.subjectRevision,
          status: "open",
        }),
      );
      // A subsequent conclusive verifier assessment supersedes findings for its criteria.
      const assessed = result.evaluations
        .filter((item) => item.verdict !== "unverified")
        .map((item) => item.criterionId);
      const findings = [
        ...state.findings.map((record): FindingRecord =>
          assessed.includes(record.finding.criterionId)
            ? {
                ...record,
                status:
                  result.evaluations.find(
                    (item) => item.criterionId === record.finding.criterionId,
                  )?.verdict === "pass"
                    ? "resolved"
                    : "superseded",
              }
            : record,
        ),
        ...findingRecords,
      ];
      const repairPlans = result.findings
        .filter((finding) => finding.severity === "blocking")
        .map((finding) => ({
          findingId: finding.findingId,
          capsule: compileVerificationTask(
            `repair_${state.dispatchCount}_${finding.findingId}`,
            state.criteria.filter(
              (criterion) => criterion.criterionId === finding.criterionId,
            ),
            state.subject!,
            finding,
          ),
        }));
      return {
        ...common,
        rows,
        findings,
        repairPlans: [...state.repairPlans, ...repairPlans],
        next: result.envelope.requiresHuman
          ? "attention"
          : rows.every((row) => row.status === "verified")
            ? "complete"
            : repairPlans.length > 0 && state.repairCount < state.maxRepairs
              ? "repair"
              : "attention",
      };
    }
    case "VerificationContinuation": {
      requireState(
        state.continuation.kind === "Emit" &&
          event.correlationId === state.continuation.event.correlationId &&
          same(event.payload, state.continuation.event.payload),
        "continuation identity",
      );
      const step = decideProgram(
        state.continuation,
        json(state),
        env(event.occurredAt),
      );
      requireState(step.emitted.length === 1, "kernel continuation emission");
      return { ...state, continuation: step.continuation! };
    }
    case "VerificationSubjectSubmitted": {
      requireState(
        state.next === "apply-repair" &&
          state.proposal &&
          state.subject &&
          state.continuation.kind === "Done",
        "repair application phase",
      );
      const subject = copySubject(value.subject as VerificationSubject);
      requireState(
        subject.repo === state.subject!.repo &&
          subject.baseCommit === state.subject!.baseCommit &&
          subject.revision !== state.subject!.revision,
        "repair revision identity",
      );
      const expected = state.subject!.files.map(
        (file) =>
          state.proposal!.replacements.find(
            (replacement) => replacement.path === file.path,
          ) ?? file,
      );
      requireState(
        same(subject.files, expected),
        "applied repair differs from proposal",
      );
      compileVerificationTask("repaired", state.criteria, subject);
      const changedSurfaces = changedVerificationSurfaces(
        state.subject!,
        subject,
      );
      requireState(changedSurfaces.length > 0, "repair must change source");
      const affected = affectedVerificationCriteria(
        state.criteria,
        changedSurfaces,
      );
      const rows = state.rows.map((row): AcceptanceEvidenceRow =>
        affected.includes(row.criterion.criterionId)
          ? {
              ...row,
              status: row.evaluations.length > 0 ? "stale" : "incomplete",
              evaluations: row.evaluations.map((evaluation) => ({
                ...evaluation,
                stale: true,
              })),
            }
          : row,
      );
      return {
        ...state,
        subject,
        rows,
        next: "verify",
        proposal: null,
        repairCount: state.repairCount + 1,
        implementerEpisodes: [
          ...state.implementerEpisodes,
          state.proposal!.envelope.episodeId,
        ],
        evidence: [...state.evidence, ...subject.evidence],
        staleness: [
          ...state.staleness,
          { eventId: event.eventId, changedSurfaces, criterionIds: affected },
        ],
      };
    }
    default:
      return state;
  }
}

export const initialVerificationRuntime = (
  workstreamId: string,
): RuntimeState => ({
  ...initialState(),
  verification: json(initialVerificationState(workstreamId)),
});
export const verificationStateFromRuntime = (
  state: RuntimeState,
): VerificationState => {
  if (state.verification === undefined)
    throw new Error("runtime lacks a verification workstream");
  return state.verification as unknown as VerificationState;
};
function verificationDecision(
  state: RuntimeState,
  event: Event,
): Decision<RuntimeState> {
  const before = verificationStateFromRuntime(state);
  const next = foldVerificationEvent(before, event);
  return {
    state: { ...state, verification: json(next) },
    intents:
      before.pending === null && next.pending !== null
        ? [next.pending.command.intent]
        : [],
    continuation: next.continuation,
    schedules: [],
    trace: {
      reactorId: "independent-verification",
      reactorVersion: "1",
      branchPath: [
        event.type,
        next.next,
        next.refusedResults.length > before.refusedResults.length
          ? "refused-result"
          : "folded",
      ],
      envInputs: [
        "event.actorId",
        "event.workstreamId",
        "event.payload",
        "event.occurredAt",
      ],
      cadenceEvaluations: [],
    },
  };
}

export interface FeedbackRuntimeState {
  readonly workstreamId: string;
  readonly program: CompiledFeedback;
  readonly workOrder: WorkOrder;
  readonly subject: string;
  readonly authority: AuthorityEnvelope;
  readonly policy: CorrectionState;
  readonly pending: Command | null;
  readonly persisted: boolean;
  readonly result: JsonValue | null;
}
export function feedbackStateFromRuntime(
  state: RuntimeState,
): FeedbackRuntimeState {
  if (state.feedback === undefined)
    throw new Error("feedback workstream not opened");
  return state.feedback as unknown as FeedbackRuntimeState;
}
/** Feedback shares the single kernel decider. All I/O remains in its host. */
function feedbackDecision(
  state: RuntimeState,
  event: Event,
): Decision<RuntimeState> {
  if (event.type === "FeedbackAuditOpened") {
    if (
      state.feedback !== undefined ||
      event.actorId !== "feedback-host" ||
      !event.workstreamId
    )
      throw new Error("feedback opening refused");
    const value = event.payload as unknown as {
      program: CompiledFeedback;
      workOrder: WorkOrder;
      subject: string;
      authority: AuthorityEnvelope;
    };
    assertCompiledFeedback(value.program);
    if (
      !same(
        value.workOrder,
        compileFeedbackAudit(
          value.program,
          value.workOrder.repo,
          value.workOrder.baseCommit,
          value.subject,
        ),
      )
    )
      throw new Error("feedback work order drift");
    const next: FeedbackRuntimeState = {
      ...value,
      workstreamId: event.workstreamId,
      pending: null,
      persisted: false,
      result: null,
      policy: {
        allowedEffects: value.authority.allowedEffects,
        destructiveEffects: ["repo.write", "repo.delete", "publish"],
        scopeExpansionAllowed: false,
        preserveEvidence: true,
        diagnosisRequired: false,
        corrections: [],
      },
    };
    return observed(
      { ...state, feedback: json(next) },
      event,
      "feedback-opened",
    );
  }
  const before = feedbackStateFromRuntime(state);
  if (event.workstreamId !== before.workstreamId)
    return observed(state, event, "feedback-outside-workstream");
  assertCompiledFeedback(before.program);
  if (
    event.actorId === "operator" &&
    SEMANTIC_CORRECTIONS.some((type) => type === event.type)
  ) {
    const policy = applyFeedbackCorrection(
      before.program,
      before.policy,
      event,
    );
    const decision = observed(
      { ...state, feedback: json({ ...before, policy }) },
      event,
      "feedback-correction",
    );
    return policy === before.policy
      ? decision
      : {
          ...decision,
          continuation: Program.Emit(
            {
              schemaVersion: 1,
              type: "FeedbackDiagnosisRequested",
              actorId: "feedback-host",
              occurredAt: event.occurredAt,
              workstreamId: event.workstreamId,
              causationId: event.eventId,
              payload: {
                correctionEventId: event.eventId,
                policyHash: before.program.policyHash,
              },
            },
            Program.Done(),
          ),
        };
  }
  if (event.actorId !== "feedback-host")
    return observed(state, event, "feedback-untrusted-event");
  if (event.type === "FeedbackAuditExecutionRequested") {
    if (
      !before.pending ||
      !before.persisted ||
      before.result ||
      before.policy.diagnosisRequired ||
      !before.policy.allowedEffects.includes("feedback.audit")
    )
      return observed(state, event, "feedback-execution-refused");
    const grant = authorize(before.pending.intent, before.authority, {
      now: event.occurredAt,
      actorId: "feedback-host",
      workstreamId: event.workstreamId!,
      episodeId: "ep_feedback_executor",
      decisionIndex: 1,
      intentIndex: 0,
      evidence: ["feedback-policy", "pinned-source"],
      revokedBy: [],
    });
    return observed(
      state,
      event,
      grant.authorized && same(grant.command, before.pending)
        ? "feedback-execution-ready"
        : "feedback-execution-refused",
    );
  }
  if (event.type === "FeedbackAuditRequested") {
    if (
      before.pending ||
      before.result ||
      before.policy.diagnosisRequired ||
      !before.policy.allowedEffects.includes("feedback.audit")
    )
      return observed(state, event, "feedback-audit-refused");
    const intent: ActIntent = {
      kind: "Act",
      effect: "feedback.audit",
      resource: "audits",
      payload: json({
        workOrder: before.workOrder,
        policyHash: before.program.policyHash,
        subject: before.subject,
      }),
    };
    const grant = authorize(intent, before.authority, {
      now: event.occurredAt,
      actorId: "feedback-host",
      workstreamId: event.workstreamId!,
      episodeId: "ep_feedback_executor",
      decisionIndex: 1,
      intentIndex: 0,
      evidence: ["feedback-policy", "pinned-source"],
      revokedBy: [],
    });
    if (!grant.authorized)
      return {
        ...observed(state, event, "feedback-authority-refused"),
        continuation: Program.Emit(grant.refusal, Program.Done()),
      };
    const program = Program.Invoke(grant.command.commandId, intent, {
      completed: Program.Done(),
    });
    const dispatched = decideProgram(program, {}, env(event.occurredAt));
    return {
      ...observed(
        { ...state, feedback: json({ ...before, pending: grant.command }) },
        event,
        "feedback-audit-dispatched",
      ),
      intents: dispatched.intents,
      continuation: program,
    };
  }
  if (event.type === "CommandPersisted") {
    const command = (event.payload as unknown as { command: Command }).command;
    if (!before.pending || before.result || !same(command, before.pending))
      throw new Error("feedback command persistence mismatch");
    return observed(
      { ...state, feedback: json({ ...before, persisted: true }) },
      event,
      "feedback-command-persisted",
    );
  }
  if (event.type === "CommandResult") {
    const result = event.payload as unknown as {
      commandId: string;
      subject: string;
      policyHash: string;
      report: JsonValue;
    };
    if (
      !before.persisted ||
      !before.pending ||
      before.result ||
      result.commandId !== before.pending.commandId ||
      result.subject !== before.subject ||
      result.policyHash !== before.program.policyHash ||
      result.report === undefined
    )
      throw new Error("feedback result mismatch");
    return {
      ...observed(
        { ...state, feedback: json({ ...before, result: result.report }) },
        event,
        "feedback-audit-executed",
      ),
      continuation: Program.Done(),
    };
  }
  return observed(state, event, "feedback-observed");
}

import {
  assertVerificationTask,
  assertCompiledFeedback,
  type CompiledFeedback,
  canonicalStringify,
  copyFinding,
  verificationLine,
  type Evaluation,
  type RepositoryFile,
  type VerificationFinding,
  type VerificationTask,
} from "@dotln/compiler";
import type { Command, ResultEnvelope, WorkOrder } from "@dotln/kernel";
import {
  planPrompt,
  planResultSchema,
  validatePlanRequest,
  validatePlanResult,
  type PlanRefutationRequest,
  type PlanRefutationResult,
} from "./plan-refutation-protocol.js";
import {
  parseWorkerResult,
  resultId,
  validateRequest,
  WorkerFailure,
  workerPrompt,
  workerResultSchema,
  type WorkerEffort,
  type WorkerRequest,
  type WorkerResult,
} from "./worker-protocol.js";

/** Fixed bound for the source-heavy feedback audit; other profiles keep WO-009 limits. */
export const FEEDBACK_VERIFIER_LIMITS = {
  timeoutMs: 600_000,
  maxBudgetUsd: "3.00",
} as const;

export interface EvidenceWorkerRequest {
  readonly feedback?: CompiledFeedback;
  readonly kind: "evidence-worker";
  readonly command: Command;
  readonly workOrder: WorkOrder;
  readonly capsule: VerificationTask;
  readonly episodeId: string;
  readonly model: string;
  readonly effort: WorkerEffort;
  readonly cwd: string;
  readonly profile: {
    readonly profileId: "verification-snapshot-v1";
    readonly mounts: readonly {
      readonly path: string;
      readonly access: "read";
    }[];
  };
}
export interface VerificationWorkerResult {
  readonly kind: "verification";
  readonly envelope: ResultEnvelope;
  readonly subjectRevision: string;
  readonly evaluations: readonly Evaluation[];
  readonly findings: readonly VerificationFinding[];
}
export interface RepairWorkerResult {
  readonly kind: "repair";
  readonly envelope: ResultEnvelope;
  readonly subjectRevision: string;
  readonly replacements: readonly RepositoryFile[];
}
export type EvidenceWorkerResult =
  VerificationWorkerResult | RepairWorkerResult;
export type TransportRequest =
  WorkerRequest | EvidenceWorkerRequest | PlanRefutationRequest;
export type TransportResult =
  WorkerResult | EvidenceWorkerResult | PlanRefutationResult;
export type TransportResultFor<R extends TransportRequest> =
  R extends PlanRefutationRequest
    ? PlanRefutationResult
    : R extends EvidenceWorkerRequest
      ? EvidenceWorkerResult
      : WorkerResult;

export const isPlanRequest = (
  request: TransportRequest,
): request is PlanRefutationRequest =>
  "kind" in request && request.kind === "plan-refutation";

export const isEvidenceRequest = (
  request: TransportRequest,
): request is EvidenceWorkerRequest =>
  "kind" in request && request.kind === "evidence-worker";
const object = (value: unknown): Record<string, unknown> | undefined =>
  value !== null && typeof value === "object" && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : undefined;
const exact = (
  value: Record<string, unknown>,
  expected: readonly string[],
): boolean =>
  Object.keys(value).sort().join(",") === [...expected].sort().join(",");
const check: (valid: unknown, reason: string) => asserts valid = (
  valid,
  reason,
) => {
  if (!valid) throw new WorkerFailure("invalid-result", reason);
};
const refs = (value: unknown): value is string[] =>
  Array.isArray(value) &&
  value.length <= 100 &&
  value.every(verificationLine) &&
  new Set(value).size === value.length;

export function parseEvidenceResult(
  value: unknown,
  request: Pick<
    EvidenceWorkerRequest,
    "command" | "workOrder" | "capsule" | "episodeId"
  >,
): EvidenceWorkerResult {
  const root = object(value);
  const envelope = object(root?.envelope);
  const verifying = request.capsule.role === "verifier";
  check(
    root &&
      envelope &&
      exact(
        root,
        verifying
          ? ["kind", "envelope", "subjectRevision", "evaluations", "findings"]
          : ["kind", "envelope", "subjectRevision", "replacements"],
      ),
    "episode result shape",
  );
  check(
    exact(envelope, [
      "workOrderId",
      "episodeId",
      "status",
      "resultId",
      "summary",
      "requiresHuman",
    ]) &&
      envelope.workOrderId === request.workOrder.workOrderId &&
      envelope.episodeId === request.episodeId &&
      envelope.resultId === resultId(request.command) &&
      verificationLine(envelope.summary) &&
      envelope.summary.length <= 320 &&
      ["completed", "failed", "blocked"].includes(String(envelope.status)) &&
      typeof envelope.requiresHuman === "boolean",
    "episode envelope",
  );
  check(
    root.subjectRevision === request.capsule.subject.revision &&
      root.kind === (verifying ? "verification" : "repair"),
    "episode role or subject",
  );
  if (!verifying) {
    check(
      Array.isArray(root.replacements) &&
        root.replacements.length <= 100 &&
        (envelope.status !== "completed" || root.replacements.length > 0),
      "repair replacements",
    );
    const seen = new Set<string>();
    for (const value of root.replacements) {
      const file = object(value);
      check(
        file &&
          exact(file, ["path", "contents"]) &&
          typeof file.path === "string" &&
          !seen.has(file.path) &&
          request.capsule.finding?.likelySurface.includes(file.path) &&
          request.capsule.subject.files.some(
            (prior) => prior.path === file.path,
          ) &&
          typeof file.contents === "string" &&
          file.contents.length <= 100_000,
        "repair outside focused surface",
      );
      seen.add(file.path);
    }
    check(
      envelope.status !== "completed" ||
        root.replacements.some(
          (file) =>
            request.capsule.subject.files.find(
              (prior) => prior.path === file.path,
            )?.contents !== file.contents,
        ),
      "repair has no substantive change",
    );
    return root as unknown as RepairWorkerResult;
  }
  check(
    Array.isArray(root.evaluations) &&
      Array.isArray(root.findings) &&
      root.findings.length <= 100 &&
      root.evaluations.length <= request.capsule.criteria.length &&
      (envelope.status !== "completed" ||
        root.evaluations.length === request.capsule.criteria.length),
    "criterion coverage",
  );
  const seen = new Set<string>();
  for (const value of root.evaluations) {
    const item = object(value);
    check(
      item &&
        exact(item, [
          "criterionId",
          "claimType",
          "verdict",
          "evidenceRefs",
          "exemplarRefs",
          "dissentRefs",
        ]) &&
        typeof item.criterionId === "string" &&
        !seen.has(item.criterionId) &&
        Array.isArray(item.exemplarRefs) &&
        item.exemplarRefs.length === 0 &&
        Array.isArray(item.dissentRefs) &&
        item.dissentRefs.length === 0,
      "evaluation shape",
    );
    const criterion = request.capsule.criteria.find(
      (criterion) => criterion.criterionId === item.criterionId,
    );
    check(
      criterion &&
        item.claimType === criterion.claimType &&
        ["pass", "fail", "unverified"].includes(String(item.verdict)) &&
        refs(item.evidenceRefs),
      "evaluation criterion",
    );
    const evidence = item.evidenceRefs.map((ref) =>
      request.capsule.subject.evidence.find(
        (entry) => entry.evidenceId === ref,
      ),
    );
    check(
      evidence.every(
        (entry) =>
          entry &&
          entry.criterionId === criterion.criterionId &&
          entry.claimType === criterion.claimType &&
          entry.source === criterion.evidenceSource,
      ),
      "claim-typed evidence",
    );
    if (item.verdict === "pass") {
      check(
        evidence.length > 0 &&
          evidence.every((entry) => entry?.outcome === "pass") &&
          criterion.requiredChecks.every((id) =>
            evidence.some((entry) => entry?.checkId === id),
          ),
        "unsupported pass",
      );
      // Omitting an adverse witness for the same required check cannot certify it.
      check(
        !request.capsule.subject.evidence.some(
          (entry) =>
            entry.criterionId === criterion.criterionId &&
            criterion.requiredChecks.includes(entry.checkId) &&
            entry.outcome !== "pass",
        ),
        "contradictory witness",
      );
    }
    if (item.verdict === "fail")
      check(
        evidence.some((entry) => entry?.outcome === "fail"),
        "unsupported failure",
      );
    seen.add(item.criterionId);
  }
  const findingIds = new Set<string>();
  for (const value of root.findings) {
    let finding: VerificationFinding;
    try {
      finding = copyFinding(value as VerificationFinding);
    } catch {
      throw new WorkerFailure("invalid-result", "finding shape");
    }
    check(
      canonicalStringify(finding) === canonicalStringify(value) &&
        !findingIds.has(finding.findingId),
      "finding shape or duplicate",
    );
    const criterion = request.capsule.criteria.find(
      (criterion) => criterion.criterionId === finding.criterionId,
    );
    const evaluation = root.evaluations.find(
      (entry) => entry.criterionId === finding.criterionId,
    );
    check(
      criterion &&
        evaluation?.verdict === "fail" &&
        finding.likelySurface.every((path) =>
          criterion.codeSurfaces.includes(path),
        ) &&
        finding.evidenceRefs.every((ref) =>
          evaluation.evidenceRefs.includes(ref),
        ),
      "finding criterion or evidence",
    );
    check(
      finding.evidenceRefs.some((ref) =>
        request.capsule.subject.evidence.some(
          (entry) =>
            entry.evidenceId === ref &&
            entry.outcome === "fail" &&
            entry.observed === finding.observed &&
            entry.expected === finding.expected,
        ),
      ),
      "finding observed versus expected",
    );
    findingIds.add(finding.findingId);
  }
  const findings = root.findings;
  check(
    root.evaluations.every(
      (item) =>
        item.verdict !== "fail" ||
        findings.some((finding) => finding.criterionId === item.criterionId),
    ),
    "failed criterion lacks finding",
  );
  return root as unknown as VerificationWorkerResult;
}

const schemaObject = (properties: Record<string, unknown>): object => ({
  type: "object",
  additionalProperties: false,
  required: Object.keys(properties),
  properties,
});
const schemaText = { type: "string" };
const schemaTexts = { type: "array", items: schemaText };
export function evidenceResultSchema(request: EvidenceWorkerRequest): object {
  const common = {
    kind: {
      ...schemaText,
      enum: [request.capsule.role === "verifier" ? "verification" : "repair"],
    },
    envelope: schemaObject({
      workOrderId: { ...schemaText, enum: [request.workOrder.workOrderId] },
      episodeId: { ...schemaText, enum: [request.episodeId] },
      resultId: { ...schemaText, enum: [resultId(request.command)] },
      status: { ...schemaText, enum: ["completed", "blocked", "failed"] },
      summary: schemaText,
      requiresHuman: { type: "boolean" },
    }),
    subjectRevision: {
      ...schemaText,
      enum: [request.capsule.subject.revision],
    },
  };
  return schemaObject(
    request.capsule.role === "repairer"
      ? {
          ...common,
          replacements: {
            type: "array",
            items: schemaObject({ path: schemaText, contents: schemaText }),
          },
        }
      : {
          ...common,
          evaluations: {
            type: "array",
            items: schemaObject({
              criterionId: schemaText,
              claimType: { ...schemaText, enum: ["state", "behavior"] },
              verdict: { ...schemaText, enum: ["pass", "fail", "unverified"] },
              evidenceRefs: schemaTexts,
              exemplarRefs: schemaTexts,
              dissentRefs: schemaTexts,
            }),
          },
          findings: {
            type: "array",
            items: schemaObject({
              findingId: schemaText,
              criterionId: schemaText,
              severity: { ...schemaText, enum: ["blocking", "major", "minor"] },
              observed: schemaText,
              expected: schemaText,
              reproductionSteps: schemaTexts,
              evidenceRefs: schemaTexts,
              likelySurface: schemaTexts,
            }),
          },
        },
  );
}

export function validateTransportRequest(request: TransportRequest): void {
  if (isPlanRequest(request)) return validatePlanRequest(request);
  if (!isEvidenceRequest(request)) return validateRequest(request);
  try {
    assertVerificationTask(request.capsule);
    if (request.feedback !== undefined)
      assertCompiledFeedback(request.feedback);
    if (
      canonicalStringify(request.workOrder) !==
        canonicalStringify(request.capsule.workOrder) ||
      request.command.intent.kind !== "Act" ||
      request.command.intent.effect !==
        request.workOrder.allowedOperations[0] ||
      canonicalStringify(request.command.intent.payload) !==
        canonicalStringify({ capsule: request.capsule }) ||
      !/^[a-zA-Z0-9][a-zA-Z0-9._:-]*$/u.test(request.model) ||
      request.model.length > 100 ||
      !/^[a-zA-Z0-9_-]+$/u.test(request.episodeId) ||
      request.profile.profileId !== "verification-snapshot-v1" ||
      request.profile.mounts.length !== 1 ||
      request.profile.mounts[0]?.path !== request.cwd ||
      request.profile.mounts[0]?.access !== "read"
    )
      throw new Error("profile mismatch");
  } catch {
    throw new WorkerFailure("profile-refused");
  }
}
export function transportResultSchema(request: TransportRequest): object {
  if (isPlanRequest(request)) return planResultSchema(request.subject);
  return isEvidenceRequest(request)
    ? evidenceResultSchema(request)
    : workerResultSchema(request);
}
export function parseTransportResult<R extends TransportRequest>(
  value: unknown,
  request: R,
): TransportResultFor<R> {
  return (
    isPlanRequest(request)
      ? validatePlanResult(value, request.subject)
      : isEvidenceRequest(request)
        ? parseEvidenceResult(value, request)
        : parseWorkerResult(value, request)
  ) as TransportResultFor<R>;
}
export function transportPrompt(request: TransportRequest): string {
  if (isPlanRequest(request)) {
    validatePlanRequest(request);
    return planPrompt(request);
  }
  if (!isEvidenceRequest(request)) return workerPrompt(request);
  validateTransportRequest(request);
  return JSON.stringify({
    capsule: request.capsule,
    episodeId: request.episodeId,
    resultId: resultId(request.command),
    outputInstructions:
      request.capsule.role === "verifier"
        ? "Independently assess each criterion using the pinned diff, repository snapshot and host witnesses. This is the complete read mount projection; no tools or other context are granted. Preserve evidence source labels. A pass requires every required check, matching claim type and source, with no adverse witness. Missing or unavailable evidence is unverified. Emit full findings for failures, blocking when repair is required. Return only the schema object; completion means this evaluation finished, never implementation success."
        : "Propose replacement contents only for the blocking finding's likely surfaces in the pinned repository snapshot. Keep the repair focused. No file writes or other tools are granted; the host applies a validated proposal in its synthetic fixture and dispatches a fresh blinded verifier. Return only the schema object. You cannot certify acceptance.",
  });
}

import {
  appendEvent,
  decodeLog,
  replay,
  type Decision,
  type Event,
  type EventDraft,
  type ResultEnvelope,
} from "@dotln/kernel";
import { canonicalStringify, type CompiledFeedback } from "@dotln/compiler";
import { WorkerStore } from "./worker-store.js";
import {
  HEARTBEAT_MS,
  LEASE_MS,
  WorkerFailure,
  type WorkerEffort,
} from "./worker-protocol.js";
import type {
  WorkOrderTransport,
  TransportDispatch,
} from "./worker-transport.js";
import {
  FEEDBACK_VERIFIER_LIMITS,
  parseEvidenceResult,
  validateTransportRequest,
  type EvidenceWorkerRequest,
  type EvidenceWorkerResult,
} from "./verification-protocol.js";
import {
  initialVerificationRuntime,
  verificationAuthorization,
  verificationDraft,
  verificationStateFromRuntime,
  type VerificationState,
} from "./verification.js";
import { seiriReactor, type RuntimeState } from "./reactor.js";

export class VerificationDriver {
  #log: string;
  #runtime: RuntimeState;
  #decisions: Decision<RuntimeState>[];
  constructor(
    readonly store: WorkerStore,
    readonly workstreamId: string,
    private readonly onEvent?: (event: Event, state: VerificationState) => void,
  ) {
    this.#log = store.read();
    const restored = replay(
      initialVerificationRuntime(workstreamId),
      decodeLog(this.#log),
      seiriReactor,
      {},
    );
    this.#runtime = restored.state;
    this.#decisions = [...restored.decisions];
  }
  get state(): VerificationState {
    return verificationStateFromRuntime(this.#runtime);
  }
  get decisions(): readonly Decision<RuntimeState>[] {
    return this.#decisions;
  }
  get log(): string {
    return this.#log;
  }
  feed(draft: EventDraft): Event {
    const appended = appendEvent(this.#log, draft);
    const decision = seiriReactor(this.#runtime, appended.event, {
      now: appended.event.occurredAt,
      rngState: 17,
      predicates: {},
    });
    // Contract/refusal checks run before committing an invalid canonical event.
    this.store.append(appended.event);
    this.#log = appended.log;
    this.#runtime = decision.state;
    this.#decisions.push(decision);
    this.onEvent?.(appended.event, this.state);
    return appended.event;
  }
  record(
    type: string,
    at: number,
    payload: unknown,
    correlationId?: string,
  ): Event {
    return this.feed(
      verificationDraft(this.workstreamId, type, at, payload, correlationId),
    );
  }
  drainContinuation(at: number): void {
    if (this.state.continuation.kind === "Emit")
      this.feed({ ...this.state.continuation.event, occurredAt: at });
  }
  persistNext(at: number): void {
    this.drainContinuation(at);
    if (!this.state.pending)
      this.record("VerificationDispatchRequested", at, {});
    if (!this.state.pending!.persisted) {
      const grant = verificationAuthorization(this.state, at);
      if (!grant.authorized) {
        this.feed(grant.refusal);
        throw new WorkerFailure("profile-refused");
      }
      if (
        canonicalStringify(grant.command) !==
        canonicalStringify(this.state.pending!.command)
      )
        throw new WorkerFailure("profile-refused");
      this.record(
        "CommandPersisted",
        at,
        {
          command: grant.command,
          authority: grant.authority,
          trace: grant.trace,
        },
        grant.command.commandId,
      );
    }
  }
  admitResult(draft: EventDraft): Event | null {
    const candidate = appendEvent(this.#log, draft).event;
    if (
      verificationStateFromRuntime(
        seiriReactor(this.#runtime, candidate, {
          now: candidate.occurredAt,
          rngState: 17,
          predicates: {},
        }).state,
      ).lastResultEventId !== candidate.eventId
    )
      return null;
    return this.feed(draft);
  }
}

export interface VerificationHostOptions {
  readonly feedback?: CompiledFeedback;
  readonly driver: VerificationDriver;
  readonly transport: WorkOrderTransport<EvidenceWorkerRequest>;
  readonly now: () => number;
  readonly afterResultSaved?: () => void;
  readonly onRunning?: (
    dispatch: TransportDispatch<EvidenceWorkerResult>,
  ) => void;
}

/** Narrow counterpart of WorkerHost for pinned verification/repair capsules. */
export class VerificationHost {
  constructor(private readonly options: VerificationHostOptions) {}
  private expire(): void {
    const { driver, now } = this.options;
    const pending = driver.state.pending;
    if (
      pending?.activeEpisode &&
      !pending.leaseExpired &&
      now() >= pending.leaseExpiresAt
    )
      driver.record(
        "WorkerLeaseExpired",
        now(),
        {
          commandId: pending.command.commandId,
          workerEpisodeId: pending.activeEpisode,
          leaseExpiresAt: pending.leaseExpiresAt,
        },
        pending.command.commandId,
      );
  }
  async run(
    cwd: string,
    model: string,
    effort: WorkerEffort,
  ): Promise<ResultEnvelope> {
    const { driver, transport, now } = this.options;
    const pending = driver.state.pending;
    if (
      !pending?.persisted ||
      !verificationAuthorization(driver.state, now()).authorized
    )
      throw new WorkerFailure("profile-refused");
    this.expire();
    const episodeId = `${pending.command.episodeId}_attempt_${pending.attempts.length + 1}`;
    const request: EvidenceWorkerRequest = {
      ...(this.options.feedback ? { feedback: this.options.feedback } : {}),
      kind: "evidence-worker",
      command: pending.command,
      capsule: pending.capsule,
      workOrder: pending.capsule.workOrder,
      episodeId,
      cwd,
      model,
      effort,
      profile: {
        profileId: "verification-snapshot-v1",
        mounts: [{ path: cwd, access: "read" }],
      },
    };
    validateTransportRequest(request);
    const cached = driver.store.loadResult(request);
    if (
      !cached &&
      driver.state.pending!.activeEpisode &&
      !driver.state.pending!.leaseExpired
    )
      throw new WorkerFailure("profile-refused", "prior episode still leased");
    driver.record(
      "WorkerAttemptStarted",
      now(),
      {
        commandId: pending.command.commandId,
        workerEpisodeId: episodeId,
        role: pending.capsule.role,
        mode: cached ? "cached-result-query" : "fresh-transport",
        inputHash: pending.capsule.inputHash,
        model,
        effort,
        transport: transport.name,
        harnessVersion: transport.harnessVersion,
        selectionSource: "host-launch",
        effectiveModel: "unknown",
        effectiveEffort: "unknown",
        ...(request.feedback
          ? {
              feedbackPolicyHash: request.feedback.policyHash,
              limits: FEEDBACK_VERIFIER_LIMITS,
            }
          : {}),
        heartbeatMs: HEARTBEAT_MS,
        leaseMs: LEASE_MS,
        leaseExpiresAt: now() + LEASE_MS,
        profileId: request.profile.profileId,
      },
      pending.command.commandId,
    );
    let result: EvidenceWorkerResult;
    if (cached) {
      result = cached;
      driver.record(
        "WorkerResultRecovered",
        now(),
        {
          commandId: pending.command.commandId,
          workerEpisodeId: episodeId,
          producingEpisodeId: result.envelope.episodeId,
        },
        pending.command.commandId,
      );
    } else {
      let timer: ReturnType<typeof setInterval> | undefined;
      let dispatch: TransportDispatch<EvidenceWorkerResult> | undefined;
      let heartbeatError: unknown;
      try {
        dispatch = transport.dispatch(request, now);
        const receipt = await dispatch.receipt;
        if (receipt.commandId !== pending.command.commandId)
          throw new WorkerFailure("invalid-result");
        driver.record(
          "CommandReceipt",
          now(),
          { ...receipt, workerEpisodeId: episodeId },
          pending.command.commandId,
        );
        timer = setInterval(() => {
          try {
            this.expire();
            if (driver.state.pending!.leaseExpired) {
              dispatch!.kill();
              return;
            }
            if (dispatch!.alive())
              driver.record(
                "WorkerHeartbeat",
                now(),
                {
                  commandId: pending.command.commandId,
                  workerEpisodeId: episodeId,
                  evidence: "host-observed-child-process",
                  leaseExpiresAt: now() + LEASE_MS,
                },
                pending.command.commandId,
              );
          } catch (error) {
            heartbeatError = error;
            dispatch!.kill();
          }
        }, HEARTBEAT_MS);
        this.options.onRunning?.(dispatch);
        result = parseEvidenceResult(await dispatch.completed, request);
        if (heartbeatError) throw heartbeatError;
      } catch (error) {
        dispatch?.kill();
        const code =
          error instanceof WorkerFailure ? error.code : "transport-failed";
        driver.record(
          "WorkerInterrupted",
          now(),
          {
            commandId: pending.command.commandId,
            workerEpisodeId: episodeId,
            reason: code,
          },
          pending.command.commandId,
        );
        throw new WorkerFailure(code);
      } finally {
        if (timer) clearInterval(timer);
      }
      if (result.envelope.status === "completed") {
        driver.store.saveResult(request, result);
        this.options.afterResultSaved?.();
      }
    }
    if (result.envelope.status !== "completed") {
      driver.record(
        "WorkerInterrupted",
        now(),
        {
          commandId: pending.command.commandId,
          workerEpisodeId: episodeId,
          reason: "worker-incomplete",
          result,
        },
        pending.command.commandId,
      );
      return result.envelope;
    }
    this.expire();
    const at = now();
    const payload = {
      commandId: pending.command.commandId,
      workerEpisodeId: episodeId,
      verificationResultVersion: 1,
      result: "completed",
      value: result,
    };
    const observation = driver.record(
      "VerificationWorkerResultObserved",
      at,
      payload,
      pending.command.commandId,
    );
    const accepted = driver.admitResult({
      ...verificationDraft(
        driver.workstreamId,
        "CommandResult",
        at,
        payload,
        pending.command.commandId,
      ),
      causationId: observation.eventId,
    });
    if (!accepted) {
      driver.record(
        "WorkerResultQuarantined",
        at,
        {
          commandId: pending.command.commandId,
          workerEpisodeId: episodeId,
          resultEventId: observation.eventId,
        },
        pending.command.commandId,
      );
      throw new WorkerFailure("profile-refused");
    }
    driver.record(
      "WorkerCompleted",
      at,
      {
        commandId: pending.command.commandId,
        workerEpisodeId: episodeId,
        envelope: result.envelope,
        resultEventId: accepted.eventId,
      },
      pending.command.commandId,
    );
    driver.drainContinuation(at);
    return result.envelope;
  }
}

import { spawn, execFileSync } from "node:child_process";
import {
  closeSync,
  fstatSync,
  mkdtempSync,
  openSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { feedbackClaudeSettings } from "./loadouts/feedback.js";
import { PLAN_REFUTATION_LIMITS } from "./plan-refutation-protocol.js";
import {
  WorkerFailure,
  WORKER_TIMEOUT_MS,
  type CommandReceipt,
  type WorkerRequest,
  type WorkerResult,
  type WorkerTransportName,
} from "./worker-protocol.js";
import {
  FEEDBACK_VERIFIER_LIMITS,
  parseTransportResult,
  validateTransportRequest,
  transportPrompt,
  transportResultSchema,
  isPlanRequest,
  type TransportRequest,
  type TransportResultFor,
} from "./verification-protocol.js";

export interface WorkerLaunch {
  readonly binary: string;
  readonly args: readonly string[];
  readonly cwd: string;
  readonly input: string;
  readonly timeoutMs: number;
}
export interface ProcessResult {
  readonly stdout: string;
  readonly stderr: string;
  readonly exitCode: number | null;
}
export interface RunningProcess {
  readonly accepted: Promise<void>;
  readonly completed: Promise<ProcessResult>;
  readonly alive: () => boolean;
  readonly kill: () => void;
}
export type ProcessRunner = (launch: WorkerLaunch) => RunningProcess;

/** No shell interpolation; raw harness output is private, bounded and discarded. */
export const runWorkerProcess: ProcessRunner = (launch) => {
  const capture = mkdtempSync(join(tmpdir(), "dotln-worker-output-"));
  const file = join(capture, "stdout");
  const fd = openSync(file, "wx", 0o600);
  const child = spawn(launch.binary, [...launch.args], {
    cwd: launch.cwd,
    stdio: ["pipe", fd, "pipe"],
    // Auth is resolved by the CLI, never copied into a prompt or log. Restrict
    // model tool environments separately in the canonical launch below.
    env: process.env,
  });
  let live = false;
  let stderr = "";
  let failure: WorkerFailure | undefined;
  const kill = () => {
    failure ??= new WorkerFailure("interrupted");
    child.kill("SIGKILL");
  };
  const accepted = new Promise<void>((resolve, reject) => {
    child.once("spawn", () => {
      live = true;
      resolve();
    });
    child.once("error", () => reject(new WorkerFailure("transport-failed")));
  });
  // Attach a rejection handler immediately even if the host first awaits spawn.
  void accepted.catch(() => {});
  const completed = new Promise<ProcessResult>((resolve, reject) => {
    const deadline = setTimeout(() => {
      failure = new WorkerFailure("deadline-exceeded");
      kill();
    }, launch.timeoutMs);
    const bound = setInterval(() => {
      if (fstatSync(fd).size > 1_000_000) {
        failure = new WorkerFailure("output-limit");
        kill();
      }
    }, 100);
    child.stderr!.on("data", (chunk: Buffer) => {
      if (stderr.length + chunk.length > 64_000) {
        failure = new WorkerFailure("output-limit");
        kill();
      } else stderr += chunk.toString("utf8");
    });
    child.stdin!.on("error", () => {
      /* early model/config refusal can close stdin */
    });
    child.once("error", () => {
      failure ??= new WorkerFailure("transport-failed");
    });
    child.once("exit", () => {
      live = false;
    });
    child.once("close", (exitCode, signal) => {
      live = false;
      clearTimeout(deadline);
      clearInterval(bound);
      try {
        if (fstatSync(fd).size > 1_000_000)
          failure = new WorkerFailure("output-limit");
        if (failure || signal)
          reject(failure ?? new WorkerFailure("interrupted"));
        else resolve({ stdout: readFileSync(file, "utf8"), stderr, exitCode });
      } finally {
        closeSync(fd);
        rmSync(capture, { recursive: true });
      }
    });
  });
  void completed.catch(() => {});
  child.stdin!.end(launch.input);
  return { accepted, completed, alive: () => live, kill };
};

export interface TransportDispatch<T = WorkerResult> {
  readonly receipt: Promise<CommandReceipt>;
  readonly completed: Promise<T>;
  readonly alive: () => boolean;
  readonly kill: () => void;
}
export interface WorkOrderTransport<
  R extends TransportRequest = WorkerRequest,
> {
  readonly name: WorkerTransportName;
  readonly harnessVersion: string;
  dispatch(
    request: R,
    now: () => number,
  ): TransportDispatch<TransportResultFor<R>>;
}

